-- ============================================================================
-- Migration 000043: Seed JLPT N4 Curriculum (10 Units, 50 Lessons, 300 Exercises)
-- Aligned 1-to-1 with GP-JA-N4-001 through GP-JA-N4-010
-- ============================================================================

DO $$
DECLARE
    v_level_id UUID;
    v_unit_id UUID;
    v_lesson_id UUID;
    v_gp_id UUID;
BEGIN
    SELECT pl.id INTO v_level_id
    FROM proficiency_levels pl
    JOIN languages l ON l.id = pl.language_id
    WHERE l.code = 'ja' AND pl.code = 'N4'
    LIMIT 1;

    IF v_level_id IS NULL THEN
        RETURN;
    END IF;

    -- Idempotent reset of N4 curriculum units (cascades to lessons & exercises)
    DELETE FROM units
    WHERE level_id = v_level_id AND unit_type = 'curriculum';

    -- ------------------------------------------------------------------------
    -- UNIT 1: Permohonan Sangat Sopan di Kantor (GP-JA-N4-001)
    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-001' LIMIT 1;

    VALUES (v_level_id, 'Permohonan Sangat Sopan di Kantor', 'Kuasai pola ～ていただけませんか untuk meminta bantuan, penjelasan ulang, dan koreksi kepada atasan, klien, maupun staf layanan secara santun.', 'curriculum', 1)
    RETURNING id INTO v_unit_id;

    -- Lesson 1.1: n4-u1-kosakata
    VALUES (v_unit_id, 'Kosakata Kantor & Layanan', 'Kosakata Kantor', 'n4-u1-kosakata', 'cards', 15, 1)
    RETURNING id INTO v_lesson_id;


    -- Lesson 1.2: n4-u1-pola-utama
    VALUES (v_unit_id, 'Pola Permohonan ～ていただけませんか', 'Pola Permohonan', 'n4-u1-pola-utama', 'book-open', 20, 2)
    RETURNING id INTO v_lesson_id;


    -- Lesson 1.3: n4-u1-dengar-baca
    VALUES (v_unit_id, 'Dengar & Baca: Situasi Kantor', 'Dengar & Baca', 'n4-u1-dengar-baca', 'play-circle', 20, 3)
    RETURNING id INTO v_lesson_id;


    -- Lesson 1.4: n4-u1-bicara-rakit
    VALUES (v_unit_id, 'Bicara & Rakit: Minta Bantuan', 'Bicara & Rakit', 'n4-u1-bicara-rakit', 'microphone', 20, 4)
    RETURNING id INTO v_lesson_id;


    -- Lesson 1.5: n4-u1-tes-akhir
    VALUES (v_unit_id, 'Tes Akhir Unit 1: Permohonan Sopan', 'Tes Unit 1', 'n4-u1-tes-akhir', 'trophy', 25, 5)
    RETURNING id INTO v_lesson_id;


    -- ------------------------------------------------------------------------
    -- UNIT 2: Keadaan Hasil Aksi Disengaja (GP-JA-N4-002)
    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-002' LIMIT 1;

    VALUES (v_level_id, 'Keadaan Hasil Aksi Disengaja', 'Gunakan pola ～てあります untuk melaporkan persiapan ruang rapat, catatan yang sudah ditulis, dan pengumuman yang sengaja dipasang.', 'curriculum', 2)
    RETURNING id INTO v_unit_id;

    -- Lesson 2.1: n4-u2-kosakata
    VALUES (v_unit_id, 'Kosakata Ruang & Pengumuman', 'Kosakata Ruang', 'n4-u2-kosakata', 'buildings', 15, 1)
    RETURNING id INTO v_lesson_id;


    -- Lesson 2.2: n4-u2-pola-utama
    VALUES (v_unit_id, 'Pola Keadaan ～てあります', 'Pola Hasil Aksi', 'n4-u2-pola-utama', 'book-open', 20, 2)
    RETURNING id INTO v_lesson_id;


    -- Lesson 2.3: n4-u2-dengar-baca
    VALUES (v_unit_id, 'Dengar & Baca: Persiapan Ruang', 'Dengar & Baca', 'n4-u2-dengar-baca', 'play-circle', 20, 3)
    RETURNING id INTO v_lesson_id;


    -- Lesson 2.4: n4-u2-bicara-rakit
