    VALUES (v_unit_id, 'Tes Akhir Unit 2: Keadaan Hasil Aksi', 'Tes Unit 2', 'n4-u2-tes-akhir', 'trophy', 25, 5)
    RETURNING id INTO v_lesson_id;


    -- ------------------------------------------------------------------------
    -- UNIT 3: Bentuk Keharusan & Aturan Kerja (GP-JA-N4-003)
    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-003' LIMIT 1;

    VALUES (v_level_id, 'Bentuk Keharusan & Aturan Kerja', 'Kuasai pola ～なければなりません untuk memahami dan menyampaikan kewajiban, prosedur keselamatan kerja, serta tenggat waktu.', 'curriculum', 3)
    RETURNING id INTO v_unit_id;

    -- Lesson 3.1: n4-u3-kosakata
    VALUES (v_unit_id, 'Kosakata Keselamatan & Jadwal', 'Aturan & Jadwal', 'n4-u3-kosakata', 'shield-check', 15, 1)
