    -- Lesson 3.5: n4-u3-tes-akhir
    VALUES (v_unit_id, 'Tes Akhir Unit 3: Bentuk Keharusan', 'Tes Unit 3', 'n4-u3-tes-akhir', 'trophy', 25, 5)
    RETURNING id INTO v_lesson_id;


    -- ------------------------------------------------------------------------
