    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-004' LIMIT 1;

    VALUES (v_level_id, 'Bentuk Potensial: Kemampuan & Fasilitas', 'Pelajari bentuk potensial (～られる / ～える) untuk menjelaskan keahlian kerja, bahasa yang dikuasai, dan fasilitas yang tersedia.', 'curriculum', 4)
    RETURNING id INTO v_unit_id;

    -- Lesson 4.1: n4-u4-kosakata
    VALUES (v_unit_id, 'Kosakata Keahlian & Fasilitas', 'Keahlian Kerja', 'n4-u4-kosakata', 'lightbulb', 15, 1)
