    RETURNING id INTO v_lesson_id;


    -- Lesson 5.3: n4-u5-dengar-baca
    VALUES (v_unit_id, 'Dengar & Baca: Bantuan Rekan', 'Dengar & Baca', 'n4-u5-dengar-baca', 'play-circle', 20, 3)
