    RETURNING id INTO v_lesson_id;


    -- Lesson 5.5: n4-u5-tes-akhir
    VALUES (v_unit_id, 'Tes Akhir Unit 5: Memberi & Menerima', 'Tes Unit 5', 'n4-u5-tes-akhir', 'trophy', 25, 5)
