    RETURNING id INTO v_unit_id;

    -- Lesson 7.1: n4-u7-kosakata
    VALUES (v_unit_id, 'Kosakata Izin & Transportasi', 'Izin & Jadwal', 'n4-u7-kosakata', 'clock', 15, 1)
    RETURNING id INTO v_lesson_id;


    -- Lesson 7.2: n4-u7-pola-utama
