    RETURNING id INTO v_lesson_id;


    -- Lesson 7.3: n4-u7-dengar-baca
    VALUES (v_unit_id, 'Dengar & Baca: Alasan Sopan', 'Dengar & Baca', 'n4-u7-dengar-baca', 'play-circle', 20, 3)
    RETURNING id INTO v_lesson_id;


    -- Lesson 7.4: n4-u7-bicara-rakit
    VALUES (v_unit_id, 'Bicara & Rakit: Minta Izin', 'Bicara & Rakit', 'n4-u7-bicara-rakit', 'microphone', 20, 4)
    RETURNING id INTO v_lesson_id;


