    -- UNIT 8: Syarat & Pengandaian (～たら) (GP-JA-N4-008)
    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N4-008' LIMIT 1;

    VALUES (v_level_id, 'Syarat & Pengandaian (～たら)', 'Kuasai pola ～たら untuk menyatakan syarat ''jika/kalau'' maupun urutan waktu ''setelah selesai'' dalam rencana akhir pekan, cuaca, dan prosedur kerja.', 'curriculum', 8)
