    VALUES (v_level_id, 'Persiapan Sebelumnya (～ておく)', 'Gunakan pola ～ておきます untuk menyatakan tindakan persiapan terlebih dahulu sebelum rapat, perjalanan, atau kegiatan rumah tangga.', 'curriculum', 9)
