    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会議の前に、この___をコピーします。', '{"options":["資料","趣味","天気","景色"],"translation":"Sebelum rapat, saya memfotokopi dokumen ini.","sentence_template":"会議の前に、この[blank]をコピーします。"}'::jsonb, '{"selected":"資料"}'::jsonb, '資料 (shiryou) berarti dokumen atau materi rapat. Pilihan lain berarti cuaca, pemandangan, dan hobi.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kata kerja kantor berikut: 先輩に新しい機械の使い方を___してもらいました。', '{"options":["運動","説明","散歩","旅行"],"translation":"Saya meminta senior menjelaskan cara menggunakan mesin baru.","sentence_template":"先輩に新しい機械の使い方を[blank]してもらいました。"}'::jsonb, '{"selected":"説明"}'::jsonb, '説明 (setsumei) berarti penjelasan; 説明する berarti menjelaskan.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang sedang dilakukan pembicara?', '{"audio_text":"すみません、受付で名前を書いてください。","options":[{"id":"opt_1","text":"Meminta menulis nama di meja resepsionis"},{"id":"opt_2","text":"Meminta membayar tagihan di kasir"},{"id":"opt_3","text":"Meminta menunggu di luar gedung"},{"id":"opt_4","text":"Meminta mengambil paket di gudang"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '受付 (uketsuke) adalah meja resepsionis, dan 名前を書いてください berarti tolong tulis nama Anda.', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Dokumen apa yang perlu diperiksa?', '{"audio_text":"部長、今日の報告書を確認お願いします。","options":[{"id":"opt_1","text":"Jadwal libur bulan depan"},{"id":"opt_2","text":"Laporan hari ini"},{"id":"opt_3","text":"Daftar hadir pelatihan"},{"id":"opt_4","text":"Kwitansi perjalanan dinas"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '報告書 (houkokusho) berarti laporan, dan 確認 (kakunin) berarti pemeriksaan atau konfirmasi.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Saya mengirim email konfirmasi kepada pelanggan."', '{"tokens":["お客様に","送ります。","駅で","確認の","食べます。","メールを"],"target_translation":"Saya mengirim email konfirmasi kepada pelanggan.","romaji":"Okyakusama ni kakunin no meeru o okurimasu."}'::jsonb, '["お客様に","確認の","メールを","送ります。"]'::jsonb, 'お客様に (kepada pelanggan) + 確認のメールを (email konfirmasi) + 送ります (mengirim).', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf mengganggu, bolehkah saya bertanya sebentar?"', '{"display_text":"すみませんが、ちょっと質問してもいいですか。","romaji":"Sumimasen ga, chotto shitsumon shite mo ii desu ka.","phonetic_breakdown":["su-mi-ma-sen","ga","chot-to","shi-tsu-mon","shi-te","mo","i-i","de-su","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、ちょっと質問してもいいですか。"}'::jsonb, 'Ungkapan すみませんが dipakai sebagai pembuka sopan sebelum mengajukan pertanyaan atau permohonan di kantor.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola permohonan sangat sopan: すみませんが、もう一度説明して___。', '{"options":["ありましたか","しまいますか","いただけませんか","いますか"],"translation":"Maaf, bersediakah Anda menjelaskannya sekali lagi?","sentence_template":"すみませんが、もう一度説明して[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, 'Pola [Verba Bentuk-TE] + いただけませんか digunakan untuk memohon bantuan dengan sangat sopan kepada atasan atau lawan bicara yang dihormati.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang tepat sebelum いただけませんか: 課長、この書類を___いただけませんか。', '{"options":["見ない","見ます","見た","見て"],"translation":"Pak Kepala Seksi, berkenankah Bapak memeriksa dokumen ini?","sentence_template":"課長、この書類を[blank]いただけませんか。"}'::jsonb, '{"selected":"見て"}'::jsonb, 'Sebelum いただけませんか, kata kerja wajib diubah ke bentuk TE: 見ます -> 見て.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah kata kerja 待ちます (menunggu) ke bentuk yang benar: 少々ここで___いただけませんか。', '{"options":["待って","待ちて","待いて","待んで"],"translation":"Bersediakah Anda menunggu sebentar di sini?","sentence_template":"少々ここで[blank]いただけませんか。"}'::jsonb, '{"selected":"待って"}'::jsonb, 'Kata kerja Grup 1 berakhiran ち (待ちます) berubah menjadi って pada bentuk TE -> 待って.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Maaf, bersediakah Anda menuliskan alamat di sini?"', '{"tokens":["書いて","住所を","すみませんが、","いただけませんか。","書きます","食べます","ここに"],"target_translation":"Maaf, bersediakah Anda menuliskan alamat di sini?","romaji":"Sumimasen ga, koko ni juusho o kaite itadakemasen ka."}'::jsonb, '["すみませんが、","ここに","住所を","書いて","いただけませんか。"]'::jsonb, '書いて (bentuk TE dari 書きます) diikuti いただけませんか membentuk permohonan sangat sopan.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda meminjamkan pulpen sebentar?"', '{"tokens":["いただけませんか。","ペンを","貸して","ちょっと","借りて","貸します"],"target_translation":"Bersediakah Anda meminjamkan pulpen sebentar?","romaji":"Chotto pen o kashite itadakemasen ka."}'::jsonb, '["ちょっと","ペンを","貸して","いただけませんか。"]'::jsonb, '貸します (meminjamkan) -> 貸して + いただけませんか. Jangan tertukar dengan 借りて (meminjam).', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bersediakah Anda berbicara sedikit lebih pelan?"', '{"display_text":"もう少しゆっくり話していただけませんか。","romaji":"Mou sukoshi yukkuri hanashite itadakemasen ka.","phonetic_breakdown":["mo-u","su-ko-shi","yuk-ku-ri","ha-na-shi-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"もう少しゆっくり話していただけませんか。"}'::jsonb, '話します -> 話して + いただけませんか sangat berguna saat berkomunikasi dengan penutur asli di tempat kerja.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan permintaan karyawan ini. Apa yang ia minta dari seniornya?', '{"audio_text":"佐藤さん、すみませんが、この漢字の読み方を教えていただけませんか。","options":[{"id":"opt_1","text":"Menulis ulang seluruh laporan"},{"id":"opt_2","text":"Mengirimkan file ke klien"},{"id":"opt_3","text":"Memberi tahu cara baca kanji tersebut"},{"id":"opt_4","text":"Memfotokopi buku manual"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'この漢字の読み方を教えていただけませんか berarti ''Bersediakah Anda memberi tahu cara baca kanji ini?''', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman di resepsionis. Apa yang diminta kepada tamu?', '{"audio_text":"恐れ入りますが、お名前と会社名をこちらにご記入いただけませんか。","options":[{"id":"opt_1","text":"Menunggu di lantai dua"},{"id":"opt_2","text":"Menunjukkan paspor asli"},{"id":"opt_3","text":"Mematikan ponsel saat rapat"},{"id":"opt_4","text":"Menuliskan nama dan nama perusahaan di formulir"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'お名前と会社名をこちらにご記入いただけませんか meminta tamu mengisi nama dan nama perusahaan dengan sangat sopan.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan permintaan di ruang rapat. Apa masalah pembicara?', '{"audio_text":"すみませんが、エアコンの温度を少し上げていただけませんか。","options":[{"id":"opt_1","text":"Ruangan terasa terlalu dingin"},{"id":"opt_2","text":"Ruangan terasa terlalu gelap"},{"id":"opt_3","text":"Proyektor tidak menyala"},{"id":"opt_4","text":"Suara mikrofon terlalu kecil"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'エアコンの温度を少し上げていただけませんか meminta menaikkan suhu AC karena ruangan terasa terlalu dingin.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kata kerja bentuk TE yang paling sesuai konteks: 荷物が重いので、ドアを___いただけませんか。', '{"options":["消して","開けて","閉めて","飲んで"],"translation":"Karena barang bawaan saya berat, bersediakah Anda membukakan pintu?","sentence_template":"荷物が重いので、ドアを[blank]いただけませんか。"}'::jsonb, '{"selected":"開けて"}'::jsonb, '開けます (membuka) -> 開けて. Konteks membawa barang berat cocok dengan meminta dibukakan pintu.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi permintaan kepada staf hotel: 明日の朝七時にタクシーを___いただけませんか。', '{"options":["呼びて","呼べて","呼んで","呼って"],"translation":"Bersediakah Anda memanggilkan taksi besok pagi pukul tujuh?","sentence_template":"明日の朝七時にタクシーを[blank]いただけませんか。"}'::jsonb, '{"selected":"呼んで"}'::jsonb, '呼びます (memanggil) berakhiran び, sehingga bentuk TE-nya adalah 呼んで.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat permintaan pengiriman data: 今日中にそのデータをメールで___いただけませんか。', '{"options":["送んで","送りて","送いて","送って"],"translation":"Bersediakah Anda mengirimkan data tersebut lewat email hari ini juga?","sentence_template":"今日中にそのデータをメールで[blank]いただけませんか。"}'::jsonb, '{"selected":"送って"}'::jsonb, '送ります (mengirim) berakhiran り, sehingga bentuk TE-nya adalah 送って.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Anda berkenan memeriksa dokumen ini?"', '{"display_text":"この資料をチェックしていただけませんか。","romaji":"Kono shiryou o chekku shite itadakemasen ka.","phonetic_breakdown":["ko-no","shi-ryo-u","o","chek-ku","shi-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"この資料をチェックしていただけませんか。"}'::jsonb, 'チェックします adalah verba Grup 3, bentuk TE-nya チェックして + いただけませんか.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, maukah Anda tolong mengambilkan foto?"', '{"display_text":"すみませんが、写真を撮っていただけませんか。","romaji":"Sumimasen ga, shashin o totte itadakemasen ka.","phonetic_breakdown":["su-mi-ma-sen","ga","sha-shin","o","tot-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、写真を撮っていただけませんか。"}'::jsonb, '写真を撮ります -> 写真を撮って + いただけませんか digunakan saat meminta orang lain mengambilkan foto secara sopan.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bersediakah Anda mengajari saya cara menggunakan mesin ini?"', '{"display_text":"この機械の使い方を教えていただけませんか。","romaji":"Kono kikai no tsukaikata o oshiete itadakemasen ka.","phonetic_breakdown":["ko-no","ki-ka-i","no","tsu-ka-i-ka-ta","o","o-shi-e-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"この機械の使い方を教えていただけませんか。"}'::jsonb, '使い方 (tsukaikata) berarti cara penggunaan; 教えます -> 教えて.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda memberitahukan nomor telepon cabang Osaka?"', '{"tokens":["大阪支店の","知って","いただけませんか。","教えて","聞きます","電話番号を"],"target_translation":"Bersediakah Anda memberitahukan nomor telepon cabang Osaka?","romaji":"Oosaka shiten no denwa bangou o oshiete itadakemasen ka."}'::jsonb, '["大阪支店の","電話番号を","教えて","いただけませんか。"]'::jsonb, 'Urutan alami: [cabang Osaka] + [nomor telepon] + を + 教えて + いただけませんか.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Maaf, bersediakah Anda mengulanginya sekali lagi?"', '{"tokens":["言って","いただけませんか。","言います","聞いて","すみませんが、","もう一度"],"target_translation":"Maaf, bersediakah Anda mengulanginya sekali lagi?","romaji":"Sumimasen ga, mou ichido itte itadakemasen ka."}'::jsonb, '["すみませんが、","もう一度","言って","いただけませんか。"]'::jsonb, '言います (mengatakan) -> Bentuk TE: 言って + いただけませんか.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda membawakan kotak ini ke ruang rapat?"', '{"tokens":["いただけませんか。","置きます","運んで","会議室まで","この箱を","運びて"],"target_translation":"Bersediakah Anda membawakan kotak ini ke ruang rapat?","romaji":"Kono hako o kaigishitsu made hakonde itadakemasen ka."}'::jsonb, '["この箱を","会議室まで","運んで","いただけませんか。"]'::jsonb, '運びます (membawa/mengangkut) berubah menjadi 運んで pada bentuk TE.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kalimat paling tepat untuk meminta tolong kepada manajer: 部長、来週のシフトについて少し___いただけませんか。', '{"options":["相談して","相談します","相談しない","相談した"],"translation":"Pak Manajer, bersediakah Bapak berdiskusi sebentar mengenai jadwal shift minggu depan?","sentence_template":"部長、来週のシフトについて少し[blank]いただけませんか。"}'::jsonb, '{"selected":"相談して"}'::jsonb, '相談します (berkonsultasi/berdiskusi) -> 相談して + いただけませんか.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi permintaan izin salinan dokumen: この契約書を一部___いただけませんか。', '{"options":["コピーします","コピーして","コピーした","コピーする"],"translation":"Bersediakah Anda memfotokopi surat kontrak ini satu rangkap?","sentence_template":"この契約書を一部[blank]いただけませんか。"}'::jsonb, '{"selected":"コピーして"}'::jsonb, '一部 (ichibu) berarti satu rangkap; コピーします -> コピーして + いただけませんか.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan telepon ini. Apa yang diminta penelepon?', '{"audio_text":"山田様はいらっしゃいませんか。それでは、お戻りにになったらお電話をいただけませんか。","options":[{"id":"opt_1","text":"Meminta agar Pak Yamada menelepon balik saat sudah kembali"},{"id":"opt_2","text":"Meminta bertemu Pak Yamada hari ini di stasiun"},{"id":"opt_3","text":"Meminta membatalkan pesanan minggu ini"},{"id":"opt_4","text":"Meminta alamat rumah Pak Yamada"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お電話をいただけませんか meminta agar pihak sana menghubungi balik dengan sangat sopan.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan dialog di kantor pos. Apa yang ingin dilakukan pelanggan?', '{"audio_text":"すみませんが、この荷物をインドネシアまで送りたいんですが、書き方を教えていただけませんか。","options":[{"id":"opt_1","text":"Menanyakan jam tutup kantor pos"},{"id":"opt_2","text":"Meminta bantuan cara mengisi formulir pengiriman ke Indonesia"},{"id":"opt_3","text":"Membeli perangko edisi khusus"},{"id":"opt_4","text":"Mengambil paket yang datang dari Indonesia"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '書き方を教えていただけませんか berarti meminta diajari cara mengisi formulir pengiriman.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bersediakah Anda menunggu sampai jam tiga?"', '{"tokens":["待って","帰って","三時まで","いただけませんか。","待ちます"],"target_translation":"Bersediakah Anda menunggu sampai jam tiga?","romaji":"Sanji made matte itadakemasen ka."}'::jsonb, '["三時まで","待って","いただけませんか。"]'::jsonb, '三時まで (sampai jam tiga) + 待って (menunggu, bentuk TE) + いただけませんか.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Maaf, bersediakah Anda membantu pekerjaan ini sebentar?"', '{"display_text":"すみませんが、この仕事を少し手伝っていただけませんか。","romaji":"Sumimasen ga, kono shigoto o sukoshi tetsudatte itadakemasen ka.","phonetic_breakdown":["su-mi-ma-sen","ga","ko-no","shi-go-to","o","su-ko-shi","te-tsu-dat-te","i-ta-da-ke-ma-sen","ka"]}'::jsonb, '{"expected_transcript":"すみませんが、この仕事を少し手伝っていただけませんか。"}'::jsonb, '手伝います (membantu) -> 手伝って + いただけませんか sangat praktis digunakan kepada rekan atau senior.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih benda yang biasa ditempel pengumuman di pabrik/kantor: 新しいシフト表が___に貼ってあります。', '{"options":["傘立て","洗濯機","掲示板","冷蔵庫"],"translation":"Jadwal shift baru sudah ditempel di papan pengumuman.","sentence_template":"新しいシフト表が[blank]に貼ってあります。"}'::jsonb, '{"selected":"掲示板"}'::jsonb, '掲示板 (keijiban) berarti papan pengumuman, tempat menempel jadwal atau informasi kerja.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata perlengkapan ruang rapat: 会議室の___の上に飲み物が並べてあります。', '{"options":["切符","ポケット","エレベーター","テーブル"],"translation":"Di atas meja ruang rapat, minuman sudah ditata rapi.","sentence_template":"会議室の[blank]の上に飲み物が並べてあります。"}'::jsonb, '{"selected":"テーブル"}'::jsonb, 'テーブル (teeburu) berarti meja. 並べてあります berarti sudah ditata dengan sengaja.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan informasi staf berikut. Di mana kunci gudang disimpan?', '{"audio_text":"倉庫の鍵は、受付の引き出しの中に入れてあります。","options":[{"id":"opt_1","text":"Di dalam laci meja resepsionis"},{"id":"opt_2","text":"Di saku baju manajer"},{"id":"opt_3","text":"Di atas rak buku ruang istirahat"},{"id":"opt_4","text":"Di dekat pintu gerbang depan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '引き出しの中 (hikidashi no naka) berarti di dalam laci.', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan ini. Apa yang terpasang di dinding?', '{"audio_text":"壁に安全ルールのポスターが貼ってあります。","options":[{"id":"opt_1","text":"Peta jalur kereta bawah tanah"},{"id":"opt_2","text":"Poster aturan keselamatan"},{"id":"opt_3","text":"Foto karyawan teladan"},{"id":"opt_4","text":"Kalender hari libur nasional"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '安全ルールのポスター (anzen ruuru no posutaa) berarti poster aturan keselamatan.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Di papan tulis sudah tertulis jadwal hari ini."', '{"tokens":["書きます","予定が","今日の","予定を","ホワイトボードに","あります。","書いて"],"target_translation":"Di papan tulis sudah tertulis jadwal hari ini.","romaji":"Howaitoboodo ni kyou no yotei ga kaite arimasu."}'::jsonb, '["ホワイトボードに","今日の","予定が","書いて","あります。"]'::jsonb, 'Pada pola ～てあります, objek yang mengalami keadaan ditandai partikel が (予定が書いてあります).', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Persiapan ruang rapat sudah selesai."', '{"display_text":"会議室の準備はもうしてあります。","romaji":"Kaigishitsu no junbi wa mou shite arimasu.","phonetic_breakdown":["ka-i-gi-shi-tsu","no","jun-bi","wa","mo-u","shi-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"会議室の準備はもうしてあります。"}'::jsonb, '準備 (junbi) berarti persiapan; もうしてあります menekankan persiapan sudah dilakukan sebelumnya.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang menyatakan keadaan hasil aksi disengaja: 窓が___。換気のために誰かが開けたようです。', '{"options":["開けてあります","開けています","開けました","開けます"],"translation":"Jendela sengaja dibiarkan terbuka. Sepertinya seseorang membukanya untuk ventilasi.","sentence_template":"窓が[blank]。換気のために誰かが開けたようです。"}'::jsonb, '{"selected":"開けてあります"}'::jsonb, '開けます (verba transitif) + てあります menyatakan jendela dalam keadaan terbuka karena sengaja dibuka untuk suatu tujuan.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih partikel yang tepat untuk pola ～てあります: 机の上にメモ___置いてあります。', '{"options":["まで","が","から","で"],"translation":"Di atas meja ada catatan yang sengaja diletakkan.","sentence_template":"机の上にメモ[blank]置いてあります。"}'::jsonb, '{"selected":"が"}'::jsonb, 'Dalam pola [Benda] が [Verba Transitif-TE] あります, partikel yang umum digunakan untuk menandai objek keadaan adalah が.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi bentuk TE verba transitif 消します (mematikan): 会議室の電気はもう___あります。', '{"options":["消えて","消って","消して","消んで"],"translation":"Lampu ruang rapat sudah dimatikan.","sentence_template":"会議室の電気はもう[blank]あります。"}'::jsonb, '{"selected":"消して"}'::jsonb, '消します (transitif: mematikan) berubah menjadi 消して + あります. 消えて adalah intransitif.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Di kalender sudah dituliskan tanggal rapat."', '{"tokens":["あります。","会議の日が","書いています","会議の日を","カレンダーに","書いて"],"target_translation":"Di kalender sudah dituliskan tanggal rapat.","romaji":"Karendaa ni kaigi no hi ga kaite arimasu."}'::jsonb, '["カレンダーに","会議の日が","書いて","あります。"]'::jsonb, 'カレンダーに (di kalender) + 会議の日が (tanggal rapat) + 書いてあります (sudah tertulis).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kursi-kursi sudah ditata rapi di aula."', '{"tokens":["並んで","並べて","あります。","いすが","きれいに","並べます","ホールに"],"target_translation":"Kursi-kursi sudah ditata rapi di aula.","romaji":"Hooru ni isu ga kirei ni narabete arimasu."}'::jsonb, '["ホールに","いすが","きれいに","並べて","あります。"]'::jsonb, '並べます adalah verba transitif (menata), sehingga 並べてあります berarti sudah ditata dengan sengaja.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di kotak ini sudah tertulis nama pemiliknya."', '{"display_text":"この箱に持ち主の名前が書いてあります。","romaji":"Kono hako ni mochinushi no namae ga kaite arimasu.","phonetic_breakdown":["ko-no","ha-ko","ni","mo-chi-nu-shi","no","na-ma-e","ga","ka-i-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"この箱に持ち主の名前が書いてあります。"}'::jsonb, '持ち主 (mochinushi) berarti pemilik; 書いてあります menunjukkan nama tersebut sengaja ditulis di kotak.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan staf ini. Bagaimana kondisi ruang rapat sekarang?', '{"audio_text":"エアコンもつけてありますし、資料も全員分並べてあります。","options":[{"id":"opt_1","text":"AC rusak dan dokumen belum dicetak"},{"id":"opt_2","text":"AC sudah dinyalakan dan dokumen sudah ditata untuk semua peserta"},{"id":"opt_3","text":"Ruang rapat sedang dipakai tim lain"},{"id":"opt_4","text":"Hanya kursi yang sudah disiapkan"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'つけてあります (AC sudah dinyalakan) dan 並べてあります (dokumen sudah ditata) menunjukkan persiapan ruang sudah lengkap.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak perlu memesan hotel lagi?', '{"audio_text":"出張のホテルはもう予約してありますから、安心してください。","options":[{"id":"opt_1","text":"Perjalanan dinas dibatalkan"},{"id":"opt_2","text":"Mereka akan menginap di rumah rekan kerja"},{"id":"opt_3","text":"Hotel untuk perjalanan dinas sudah dipesan sebelumnya"},{"id":"opt_4","text":"Mereka pulang di hari yang sama"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '予約してあります berarti sudah dipesan sebelumnya untuk tujuan perjalanan dinas.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan petunjuk di dapur kantor. Di mana kopi disiapkan?', '{"audio_text":"お客様用のコーヒーは、ポットに作ってありますよ。","options":[{"id":"opt_1","text":"Belum dibuat karena air belum panas"},{"id":"opt_2","text":"Harus dibeli di minimarket depan"},{"id":"opt_3","text":"Disimpan di dalam kulkas"},{"id":"opt_4","text":"Sudah dibuat dan berada di dalam teko termos"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'ポットに作ってあります berarti sudah diseduh/dibuat dan ditaruh di dalam teko termos.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat laporan persiapan dokumen: 明日のプレゼンの資料はもう印刷して___。', '{"options":["きます","みます","いきます","あります"],"translation":"Materi presentasi besok sudah selesai dicetak.","sentence_template":"明日のプレゼンの資料はもう印刷して[blank]。"}'::jsonb, '{"selected":"あります"}'::jsonb, '印刷してあります menekankan bahwa pencetakan sudah selesai dilakukan untuk persiapan presentasi besok.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kata kerja transitif yang tepat untuk pintu: 防犯のために、裏口には鍵が___あります。', '{"options":["かけて","あいて","しまって","かかって"],"translation":"Demi keamanan, pintu belakang sudah dikunci.","sentence_template":"防犯のために、裏口には鍵が[blank]あります。"}'::jsonb, '{"selected":"かけて"}'::jsonb, '鍵をかけます (mengunci, transitif) -> 鍵がかけてあります. かかって adalah bentuk intransitif.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi informasi yang tertera pada kemasan obat: この薬の箱に飲み方が詳しく___あります。', '{"options":["見て","書いて","聞いて","読んで"],"translation":"Di kotak obat ini sudah tertulis cara minumnya secara rinci.","sentence_template":"この薬の箱に飲み方が詳しく[blank]あります。"}'::jsonb, '{"selected":"書いて"}'::jsonb, '書いてあります menyatakan informasi yang memang sengaja dicetak/ditulis pada kemasan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di depan pintu masuk sudah diletakkan bunga yang indah."', '{"display_text":"玄関の前にきれいな花が飾ってあります。","romaji":"Genkan no mae ni kirei na hana ga kazatte arimasu.","phonetic_breakdown":["gen-kan","no","ma-e","ni","ki-re-i","na","ha-na","ga","ka-zat-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"玄関の前にきれいな花が飾ってあります。"}'::jsonb, '飾ります (menghias/memajang) -> 飾ってあります berarti sudah dipajang dengan sengaja.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tiket kereta sudah saya beli kemarin."', '{"display_text":"電車の切符は昨日もう買ってあります。","romaji":"Densha no kippu wa kinou mou katte arimasu.","phonetic_breakdown":["den-sha","no","kip-pu","wa","ki-no-u","mo-u","kat-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"電車の切符は昨日もう買ってあります。"}'::jsonb, '買ってあります menunjukkan tiket sudah dibeli sebelumnya sebagai persiapan perjalanan.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di meja resepsionis sudah disiapkan peta gedung."', '{"display_text":"受付に建物の地図が置いてあります。","romaji":"Uketsuke ni tatemono no chizu ga oite arimasu.","phonetic_breakdown":["u-ke-tsu-ke","ni","ta-te-mo-no","no","chi-zu","ga","o-i-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"受付に建物の地図が置いてあります。"}'::jsonb, '置きます (meletakkan) -> 置いてあります berarti sudah diletakkan agar tamu bisa mengambilnya.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Di dalam kulkas sudah didinginkan minuman."', '{"tokens":["冷えて","飲みます","冷蔵庫に","冷やして","あります。","飲み物が"],"target_translation":"Di dalam kulkas sudah didinginkan minuman.","romaji":"Reizouko ni nomimono ga hiyashite arimasu."}'::jsonb, '["冷蔵庫に","飲み物が","冷やして","あります。"]'::jsonb, '冷やします (mendinginkan, transitif) -> 冷やしてあります.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Di pintu sudah ditempel pengumuman hari libur."', '{"tokens":["お知らせを","お知らせが","貼って","あります。","休みの","ドアに","貼ります"],"target_translation":"Di pintu sudah ditempel pengumuman hari libur.","romaji":"Doa ni yasumi no oshirase ga hatte arimasu."}'::jsonb, '["ドアに","休みの","お知らせが","貼って","あります。"]'::jsonb, '貼ります (menempelkan) -> 貼ってあります, dengan subjek keadaan お知らせが.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meja makan sudah dibersihkan sebelum tamu datang."', '{"tokens":["拭きます","拭いて","きれいに","テーブルが","汚れて","あります。","お客様が来る前に、"],"target_translation":"Meja makan sudah dibersihkan sebelum tamu datang.","romaji":"Okyakusama ga kuru mae ni, teeburu ga kirei ni fuite arimasu."}'::jsonb, '["お客様が来る前に、","テーブルが","きれいに","拭いて","あります。"]'::jsonb, '拭きます (mengelap) -> 拭いてあります menyatakan meja sudah dalam kondisi bersih terlap.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kalimat yang tepat untuk menyatakan ruangan sudah dirapikan: お客様が来るので、応接室はもう___。', '{"options":["片付きました","片付けています","片付けてあります","片付けます"],"translation":"Karena tamu akan datang, ruang tamu kantor sudah dirapikan.","sentence_template":"お客様が来るので、応接室はもう[blank]。"}'::jsonb, '{"selected":"片付けてあります"}'::jsonb, '片付けます (merapikan, transitif) + てあります menekankan kesiapan ruangan untuk tamu.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat tentang petunjuk yang tertulis di mesin: このボタンの横に「緊急停止」と___あります。', '{"options":["話して","持って","送って","書いて"],"translation":"Di samping tombol ini tertulis ''Berhenti Darurat''.","sentence_template":"このボタンの横に「緊急停止」と[blank]あります。"}'::jsonb, '{"selected":"書いて"}'::jsonb, '「...」と書いてあります adalah pola sangat umum di Jepang untuk membaca label atau rambu.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja ini. Apa yang sudah dilakukan Tanaka?', '{"audio_text":"田中さん、明日の会議の弁当は注文しましたか。ええ、十個注文してあります。","options":[{"id":"opt_1","text":"Tanaka sudah memesan sepuluh kotak bento untuk rapat besok"},{"id":"opt_2","text":"Tanaka lupa memesan makanan untuk rapat"},{"id":"opt_3","text":"Tanaka akan memesan bento besok pagi"},{"id":"opt_4","text":"Rapat besok tidak menyediakan makan siang"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '十個注文してあります berarti sepuluh kotak sudah dipesan sebelumnya.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang loker. Di mana helm kerja berada?', '{"audio_text":"新しいヘルメットは、自分のロッカーの中に入れてありますので、確認してください。","options":[{"id":"opt_1","text":"Di gudang lantai satu"},{"id":"opt_2","text":"Di dalam loker masing-masing"},{"id":"opt_3","text":"Di meja kepala bagian"},{"id":"opt_4","text":"Di pintu masuk pabrik"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '自分のロッカーの中に入れてあります berarti sudah dimasukkan ke dalam loker masing-masing.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Proyektor sudah dinyalakan di ruang rapat."', '{"tokens":["つけて","あります。","会議室で","つけます","ついて","プロジェクターが"],"target_translation":"Proyektor sudah dinyalakan di ruang rapat.","romaji":"Kaigishitsu de purojekutaa ga tsukete arimasu."}'::jsonb, '["会議室で","プロジェクターが","つけて","あります。"]'::jsonb, 'つけます (menyalakan, transitif) -> つけてあります.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semua dokumen yang diperlukan sudah dimasukkan ke dalam map."', '{"display_text":"必要な書類は全部ファイルに入れてあります。","romaji":"Hitsuyou na shorui wa zenbu fairu ni irete arimasu.","phonetic_breakdown":["hi-tsu-yo-u","na","sho-ru-i","wa","zen-bu","fa-i-ru","ni","i-re-te","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"必要な書類は全部ファイルに入れてあります。"}'::jsonb, '入れます (memasukkan) -> 入れてあります menyatakan semua berkas sudah rapi tersimpan di map.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''batas waktu / tenggat'': このレポートの___は今週の金曜日です。', '{"options":["締め切り","お祝い","乗り換え","思い出"],"translation":"Tenggat waktu laporan ini adalah hari Jumat minggu ini.","sentence_template":"このレポートの[blank]は今週の金曜日です。"}'::jsonb, '{"selected":"締め切り"}'::jsonb, '締め切り (shimekiri) berarti batas waktu atau deadline pengumpulan.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata perlengkapan keselamatan kerja: 工場に入る前に、必ず___をかぶります。', '{"options":["サングラス","ヘルメット","スリッパ","ネクタイ"],"translation":"Sebelum masuk pabrik, wajib mengenakan helm pengaman.","sentence_template":"工場に入る前に、必ず[blank]をかぶります。"}'::jsonb, '{"selected":"ヘルメット"}'::jsonb, 'ヘルメットをかぶります berarti memakai helm (kata kerja untuk penutup kepala adalah かぶる).', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan aturan kantor berikut. Apa yang harus dilakukan saat terlambat?', '{"audio_text":"遅刻するときは、必ず開始前に上司へ連絡してください。","options":[{"id":"opt_1","text":"Langsung pulang ke rumah"},{"id":"opt_2","text":"Menunggu sampai jam istirahat"},{"id":"opt_3","text":"Menghubungi atasan sebelum jam kerja dimulai"},{"id":"opt_4","text":"Mengirim surat ke bagian keuangan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '遅刻するとき (saat terlambat) + 上司へ連絡 (menghubungi atasan).', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di klinik. Apa yang harus dibawa pasien?', '{"audio_text":"病院へ行くときは、健康保険証を忘れないでください。","options":[{"id":"opt_1","text":"Kartu perpustakaan"},{"id":"opt_2","text":"Buku tabungan bank"},{"id":"opt_3","text":"Kartu pelajar"},{"id":"opt_4","text":"Kartu asuransi kesehatan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '健康保険証 (kenkou hokenshou) adalah kartu asuransi kesehatan di Jepang.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum bekerja, saya memeriksa kondisi mesin."', '{"tokens":["状態を","忘れます。","確認します。","作業の前に、","機械の","機械が"],"target_translation":"Sebelum bekerja, saya memeriksa kondisi mesin.","romaji":"Sagyou no mae ni, kikai no joutai o kakunin shimasu."}'::jsonb, '["作業の前に、","機械の","状態を","確認します。"]'::jsonb, '作業 (sagyou) berarti pekerjaan/operasi lapangan; 状態 (joutai) berarti kondisi.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Aturan keselamatan harus selalu dipatuhi."', '{"display_text":"安全ルールは必ず守ります。","romaji":"Anzen ruuru wa kanarazu mamorimasu.","phonetic_breakdown":["an-zen","ru-u-ru","wa","ka-na-ra-zu","ma-mo-ri-ma-su"]}'::jsonb, '{"expected_transcript":"安全ルールは必ず守ります。"}'::jsonb, '必ず (kanarazu) berarti pasti/wajib, dan ルールを守る berarti mematuhi aturan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 提出します (mengumpulkan) ke pola keharusan: 明日までにこの書類を___。', '{"options":["提出してなりません","提出したなりません","提出しなければなりません","提出しますなりません"],"translation":"Saya harus mengumpulkan dokumen ini paling lambat besok.","sentence_template":"明日までにこの書類を[blank]。"}'::jsonb, '{"selected":"提出しなければなりません"}'::jsonb, 'Pola keharusan: ubah verba ke bentuk NAI (提出しない), buang い, lalu tambah ければなりません.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih konjugasi bentuk NAI yang tepat dari 行きます: 明日は八時に会社へ___なりません。', '{"options":["行ってければ","行きなければ","行くければ","行かなければ"],"translation":"Besok saya harus pergi ke kantor pukul delapan.","sentence_template":"明日は八時に会社へ[blank]なりません。"}'::jsonb, '{"selected":"行かなければ"}'::jsonb, '行きます -> Bentuk NAI: 行かない -> hilangkan い -> 行かなければなりません.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kewajiban membayar sewa rumah: 毎月二十五日までに家賃を___なりません。', '{"options":["払わなければ","払うければ","払ってければ","払いないければ"],"translation":"Setiap bulan saya harus membayar uang sewa paling lambat tanggal 25.","sentence_template":"毎月二十五日までに家賃を[blank]なりません。"}'::jsonb, '{"selected":"払わなければ"}'::jsonb, '払います berakhiran い (Grup 1) -> bentuk NAI menjadi 払わない -> 払わなければなりません.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya harus mencuci tangan sebelum masuk ruang produksi."', '{"tokens":["洗って","入る前に、","作業室に","洗わなければ","手を","なりません。","洗います"],"target_translation":"Saya harus mencuci tangan sebelum masuk ruang produksi.","romaji":"Sagyoushitsu ni hairu mae ni, te o arawanakereba narimasen."}'::jsonb, '["作業室に","入る前に、","手を","洗わなければ","なりません。"]'::jsonb, '洗います -> 洗わない -> 洗わなければなりません (harus mencuci).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Hari ini saya harus lembur sampai jam delapan."', '{"tokens":["今日は","残業して","八時まで","なりません。","残業しなければ","残業します"],"target_translation":"Hari ini saya harus lembur sampai jam delapan.","romaji":"Kyou wa hachiji made zangyou shinakereba narimasen."}'::jsonb, '["今日は","八時まで","残業しなければ","なりません。"]'::jsonb, '残業します (lembur) -> 残業しない -> 残業しなければなりません.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya harus meminum obat ini setelah makan."', '{"display_text":"食後にこの薬を飲まなければなりません。","romaji":"Shokugo ni kono kusuri o nomanakereba narimasen.","phonetic_breakdown":["sho-ku-go","ni","ko-no","ku-su-ri","o","no-ma-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"食後にこの薬を飲まなければなりません。"}'::jsonb, '飲みます -> 飲まない -> 飲まなければなりません. 食後 (shokugo) berarti setelah makan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan kepala pabrik. Apa yang wajib dipakai di area kerja?', '{"audio_text":"この工場では、作業中に必ず手袋とマスクをつけなければなりません。","options":[{"id":"opt_1","text":"Sarung tangan dan masker"},{"id":"opt_2","text":"Jas hujan dan sepatu bot"},{"id":"opt_3","text":"Dasi dan kemeja putih"},{"id":"opt_4","text":"Kacamata hitam dan topi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '手袋 (tebukuro) berarti sarung tangan, dan マスク (masuku) berarti masker.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa Andi pulang lebih awal?', '{"audio_text":"すみません、今日は五時に市役所へ行かなければなりませんので、先に失礼します。","options":[{"id":"opt_1","text":"Karena dia sedang demam tinggi"},{"id":"opt_2","text":"Karena dia harus pergi ke kantor balai kota pukul lima"},{"id":"opt_3","text":"Karena keluarganya datang dari Indonesia"},{"id":"opt_4","text":"Karena keretanya akan berhenti beroperasi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '市役所へ行かなければなりません berarti harus pergi ke kantor balai kota (shiyakusho).', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman asrama. Kapan sampah plastik harus dibuang?', '{"audio_text":"プラスチックごみは、毎週水曜日の朝八時までに出さなければなりません。","options":[{"id":"opt_1","text":"Setiap Senin malam"},{"id":"opt_2","text":"Setiap Jumat siang"},{"id":"opt_3","text":"Setiap Rabu pagi paling lambat jam delapan"},{"id":"opt_4","text":"Kapan saja sepanjang minggu"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '毎週水曜日の朝八時までに出さなければなりません berarti harus dikeluarkan setiap Rabu pagi maksimal jam 8.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi aturan membawa kartu identitas di Jepang: 外国人はいつでも在留カードを___なりません。', '{"options":["持っていますければ","持っていなければ","持つければ","持ったければ"],"translation":"Warga asing harus selalu membawa kartu izin tinggal (Zairyu Card).","sentence_template":"外国人はいつでも在留カードを[blank]なりません。"}'::jsonb, '{"selected":"持っていなければ"}'::jsonb, '持っています -> 持っていない -> 持っていなければなりません.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kata kerja keharusan untuk mengembalikan buku: 図書館の本は二週間以内に___なりません。', '{"options":["返しなければ","返してければ","返さなければ","返るければ"],"translation":"Buku perpustakaan harus dikembalikan dalam waktu dua minggu.","sentence_template":"図書館の本は二週間以内に[blank]なりません。"}'::jsonb, '{"selected":"返さなければ"}'::jsonb, '返します (mengembalikan) -> 返さない -> 返さなければなりません.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kewajiban memperbarui visa: 来月までにビザを___なりません。', '{"options":["更新してければ","更新するければ","更新したければ","更新しなければ"],"translation":"Saya harus memperbarui visa paling lambat bulan depan.","sentence_template":"来月までにビザを[blank]なりません。"}'::jsonb, '{"selected":"更新しなければ"}'::jsonb, '更新します (memperbarui/renew) -> 更新しない -> 更新しなければなりません.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di kantor ini kita harus memakai sepatu kerja khusus."', '{"display_text":"ここでは専用の作業靴を履かなければなりません。","romaji":"Koko de wa senyou no sagyougutsu o hakanakereba narimasen.","phonetic_breakdown":["ko-ko","de","wa","sen-yo-u","no","sa-gyo-u-gu-tsu","o","ha-ka-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"ここでは専用の作業靴を履かなければなりません。"}'::jsonb, '履きます (memakai alas kaki) -> 履かない -> 履かなければなりません.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum pulang, kita harus mematikan semua komputer."', '{"display_text":"帰る前に、パソコンの電源を全部切らなければなりません。","romaji":"Kaeru mae ni, pasokon no dengen o zenbu kiranakereba narimasen.","phonetic_breakdown":["ka-e-ru","ma-e","ni","pa-so-kon","no","den-gen","o","zen-bu","ki-ra-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"帰る前に、パソコンの電源を全部切らなければなりません。"}'::jsonb, '電源を切ります (mematikan daya) -> 切らない -> 切らなければなりません.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Besok pagi saya harus bangun jam lima."', '{"display_text":"明日の朝は五時に起きなければなりません。","romaji":"Ashita no asa wa goji ni okinakereba narimasen.","phonetic_breakdown":["a-shi-ta","no","a-sa","wa","go-ji","ni","o-ki-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日の朝は五時に起きなければなりません。"}'::jsonb, '起きます (Grup 2) -> 起きない -> 起きなければなりません.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kita harus menulis laporan setiap hari sebelum pulang."', '{"tokens":["帰る前に","なりません。","毎日","書きます","書かなければ","書いて","日報を"],"target_translation":"Kita harus menulis laporan setiap hari sebelum pulang.","romaji":"Mainichi kaeru mae ni nippou o kakanakereba narimasen."}'::jsonb, '["毎日","帰る前に","日報を","書かなければ","なりません。"]'::jsonb, '日報 (nippou) adalah laporan harian kerja; 書きます -> 書かなければなりません.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Di dalam kereta kita harus mematikan suara ponsel."', '{"tokens":["マナーモードに","なりません。","しなければ","電車の中では","します","した","携帯を"],"target_translation":"Di dalam kereta kita harus mematikan suara ponsel.","romaji":"Densha no naka de wa keitai o manaamoodo ni shinakereba narimasen."}'::jsonb, '["電車の中では","携帯を","マナーモードに","しなければ","なりません。"]'::jsonb, 'マナーモードにします (mengatur ke mode senyap) -> しなければなりません.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya harus segera menghubungi manajer."', '{"tokens":["部長に","すぐに","連絡します","連絡して","なりません。","連絡しなければ"],"target_translation":"Saya harus segera menghubungi manajer.","romaji":"Sugu ni buchou ni renraku shinakereba narimasen."}'::jsonb, '["すぐに","部長に","連絡しなければ","なりません。"]'::jsonb, 'すぐに (segera) + 部長に (kepada manajer) + 連絡しなければなりません.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk keharusan yang tepat untuk kata kerja 来ます (datang): 明日は九時までに駅へ___なりません。', '{"options":["来なければ","来てければ","来るければ","来いなければ"],"translation":"Besok saya harus datang ke stasiun paling lambat jam sembilan.","sentence_template":"明日は九時までに駅へ[blank]なりません。"}'::jsonb, '{"selected":"来なければ"}'::jsonb, '来ます (kimasu, Grup 3) bentuk NAI-nya adalah 来ない (konai) -> 来なければなりません (konakereba narimasen).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi aturan keamanan data perusahaan: 会社のパソコンのパスワードは定期的に___なりません。', '{"options":["変えてければ","変えなければ","変えるければ","変えします"],"translation":"Kata sandi komputer perusahaan harus diganti secara berkala.","sentence_template":"会社のパソコンのパスワードは定期的に[blank]なりません。"}'::jsonb, '{"selected":"変えなければ"}'::jsonb, '変えます (mengubah, Grup 2) -> 変えない -> 変えなければなりません.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak bisa ikut makan malam?', '{"audio_text":"すみません、今夜は明日の試験のために勉強しなければならないんです。","options":[{"id":"opt_1","text":"Dia harus menjemput temannya di bandara"},{"id":"opt_2","text":"Dia sudah makan sebelumnya"},{"id":"opt_3","text":"Dia kehabisan uang tunai"},{"id":"opt_4","text":"Dia harus belajar untuk ujian besok"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '明日の試験のために勉強しなければならない berarti harus belajar untuk ujian besok.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan instruksi kebersihan dapur. Kapan celemek harus diganti?', '{"audio_text":"エプロンが汚れたら、すぐに新しいものに交換しなければなりません。","options":[{"id":"opt_1","text":"Segera diganti dengan yang baru begitu kotor"},{"id":"opt_2","text":"Diganti seminggu sekali"},{"id":"opt_3","text":"Diganti hanya saat ada inspeksi"},{"id":"opt_4","text":"Tidak perlu diganti sampai shift selesai"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '汚れたらすぐに新しいものに交換しなければなりません berarti jika kotor harus segera diganti dengan yang baru.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saat masuk rumah orang Jepang, kita harus melepas sepatu."', '{"tokens":["脱がなければ","履かなければ","入るときは、","靴を","脱いで","日本の家に","なりません。"],"target_translation":"Saat masuk rumah orang Jepang, kita harus melepas sepatu.","romaji":"Nihon no ie ni hairu toki wa, kutsu o nuganakereba narimasen."}'::jsonb, '["日本の家に","入るときは、","靴を","脱がなければ","なりません。"]'::jsonb, '脱ぎます (melepas sepatu/pakaian) -> 脱がない -> 脱がなければなりません.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena besok ada rapat penting, saya tidak boleh terlambat dan harus datang lebih awal."', '{"display_text":"明日は大事な会議があるので、早く来なければなりません。","romaji":"Ashita wa daiji na kaigi ga aru node, hayaku konakereba narimasen.","phonetic_breakdown":["a-shi-ta","wa","da-i-ji","na","ka-i-gi","ga","a-ru","no-de","ha-ya-ku","ko-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日は大事な会議があるので、早く来なければなりません。"}'::jsonb, '来なければなりません dibaca ''konakereba narimasen'' (bukan kinakereba).', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''SIM / surat izin mengemudi'': 日本で車の___を取りました。', '{"options":["切手","住所","免許","領収書"],"translation":"Saya sudah mendapatkan SIM mobil di Jepang.","sentence_template":"日本で車の[blank]を取りました。"}'::jsonb, '{"selected":"免許"}'::jsonb, '免許 (menkyo) berarti lisensi atau SIM (運転免許).', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata pembayaran di toko Jepang: このお店ではクレジットカードで___ができます。', '{"options":["洗濯","引っ越し","散歩","支払い"],"translation":"Di toko ini bisa melakukan pembayaran dengan kartu kredit.","sentence_template":"このお店ではクレジットカードで[blank]ができます。"}'::jsonb, '{"selected":"支払い"}'::jsonb, '支払い (shiharai) berarti pembayaran; 支払いができる berarti bisa membayar.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan perkenalan diri di wawancara kerja. Apa keahlian pelamar?', '{"audio_text":"私は英語とインドネシア語が話せます。エクセルも使えます。","options":[{"id":"opt_1","text":"Bisa memasak makanan Jepang dan Prancis"},{"id":"opt_2","text":"Bisa berbahasa Inggris, Indonesia, dan menggunakan Excel"},{"id":"opt_3","text":"Bisa mengemudikan truk besar"},{"id":"opt_4","text":"Bisa memperbaiki mesin pendingin"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '英語とインドネシア語が話せます (bisa bicara Inggris & Indonesia) dan エクセルも使えます (bisa memakai Excel).', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan informasi fasilitas apartemen. Apa yang tersedia gratis?', '{"audio_text":"このアパートでは、高速のワイファイが無料で使えます。","options":[{"id":"opt_1","text":"Sarapan pagi setiap hari"},{"id":"opt_2","text":"Layanan antar-jemput stasiun"},{"id":"opt_3","text":"Wi-Fi berkecepatan tinggi gratis"},{"id":"opt_4","text":"Tempat parkir mobil pribadi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '無料で使えます (muryou de tsukaemasu) berarti dapat digunakan secara gratis.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Di stasiun ini kita bisa naik kereta cepat."', '{"tokens":["乗ります。","急行電車に","この駅で","乗れます。","歩きます。"],"target_translation":"Di stasiun ini kita bisa naik kereta cepat.","romaji":"Kono eki de kyuukou densha ni noremasu."}'::jsonb, '["この駅で","急行電車に","乗れます。"]'::jsonb, '乗ります (naik kendaraan) berubah ke bentuk potensial menjadi 乗れます (bisa naik).', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bisa mengoperasikan komputer dengan lancar."', '{"display_text":"私はパソコンの操作ができます。","romaji":"Watashi wa pasokon no sousa ga dekimasu.","phonetic_breakdown":["wa-ta-shi","wa","pa-so-kon","no","so-u-sa","ga","de-ki-ma-su"]}'::jsonb, '{"expected_transcript":"私はパソコンの操作ができます。"}'::jsonb, '操作 (sousa) berarti pengoperasian; ～ができます menyatakan kemampuan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 話します (berbicara, Grup 1) ke bentuk potensial: 弟は日本語が少し___。', '{"options":["話せます","話します","話せります","話しられます"],"translation":"Adik laki-laki saya bisa berbicara bahasa Jepang sedikit.","sentence_template":"弟は日本語が少し[blank]。"}'::jsonb, '{"selected":"話せます"}'::jsonb, 'Verba Grup 1 mengubah bunyi vokal ''i'' sebelum ます menjadi ''e'': 話します (hanashimasu) -> 話せます (hanasemasu).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 食べます (makan, Grup 2) ke bentuk potensial: 私は辛い料理も___。', '{"options":["食べます","食べられます","食べえます","食べれます"],"translation":"Saya juga bisa makan masakan pedas.","sentence_template":"私は辛い料理も[blank]。"}'::jsonb, '{"selected":"食べられます"}'::jsonb, 'Verba Grup 2 baku menambahkan られます pada akar kata: 食べます -> 食べられます.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih partikel objek yang paling tepat untuk bentuk potensial: 漢字___三百字ぐらい読めます。', '{"options":["で","に","が","へ"],"translation":"Saya bisa membaca sekitar tiga ratus huruf kanji.","sentence_template":"漢字[blank]三百字ぐらい読めます。"}'::jsonb, '{"selected":"が"}'::jsonb, 'Objek dari kata kerja bentuk potensial umumnya ditandai dengan partikel が (漢字が読めます).', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa menulis email dalam bahasa Jepang."', '{"tokens":["書けます。","メールが","書きます。","メールを","日本語で"],"target_translation":"Saya bisa menulis email dalam bahasa Jepang.","romaji":"Nihongo de meeru ga kakemasu."}'::jsonb, '["日本語で","メールが","書けます。"]'::jsonb, '書きます (Grup 1) -> 書けます (bisa menulis), dengan objek ditandai が.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Anda bisa datang ke pesta besok?"', '{"tokens":["パーティーに","明日の","来られますか。","行きますか。","来ますか。"],"target_translation":"Apakah Anda bisa datang ke pesta besok?","romaji":"Ashita no paatii ni koraremasu ka."}'::jsonb, '["明日の","パーティーに","来られますか。"]'::jsonb, '来ます (Grup 3) memiliki bentuk potensial tidak beraturan: 来られます (koraremasu).', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di sini tidak bisa membayar dengan uang tunai."', '{"display_text":"ここでは現金で払えません。","romaji":"Koko de wa genkin de haraemasen.","phonetic_breakdown":["ko-ko","de","wa","gen-kin","de","ha-ra-e-ma-sen"]}'::jsonb, '{"expected_transcript":"ここでは現金で払えません。"}'::jsonb, '払います -> 払えます (bisa bayar) -> 払えません (tidak bisa bayar).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan resepsionis hotel. Fasilitas apa yang bisa dipakai sampai malam?', '{"audio_text":"大浴場は夜の十一時まで入れますので、ぜひご利用ください。","options":[{"id":"opt_1","text":"Restoran prasmanan"},{"id":"opt_2","text":"Ruang rapat lantai tiga"},{"id":"opt_3","text":"Kolam renang luar ruangan"},{"id":"opt_4","text":"Pemandian air panas umum sampai jam 11 malam"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '大浴場 (daiyokujou) adalah pemandian umum besar, dan 入れます (hairemasu) berarti bisa masuk/menggunakan.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa Rina tidak ikut menyetir?', '{"audio_text":"免許は持っていますが、雪の日は危ないので運転できません。","options":[{"id":"opt_1","text":"Dia tidak bisa menyetir saat hari bersalju karena berbahaya"},{"id":"opt_2","text":"Dia belum memiliki SIM"},{"id":"opt_3","text":"Mobilnya sedang diperbaiki di bengkel"},{"id":"opt_4","text":"Dia tidak tahu jalan menuju kantor cabang"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '運転できません berarti tidak bisa mengemudi; 免許は持っています berarti dia sebenarnya punya SIM.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan informasi minimarket ini. Layanan apa yang tersedia di mesin ATM?', '{"audio_text":"このATMでは、二十四時間いつでもお金がおろせます。","options":[{"id":"opt_1","text":"Hanya bisa menukar mata uang asing"},{"id":"opt_2","text":"Bisa menarik uang tunai kapan saja selama 24 jam"},{"id":"opt_3","text":"Hanya buka pada hari kerja"},{"id":"opt_4","text":"Bisa mencetak tiket pesawat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'お金がおろせます berarti bisa menarik uang (おろします -> おろせます).', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk potensial dari 見ます (melihat, Grup 2): 晴れた日には、この窓から富士山が___。', '{"options":["見ます","見えます","見れります","見られます"],"translation":"Pada hari cerah, dari jendela ini kita dapat menyaksikan Gunung Fuji.","sentence_template":"晴れた日には、この窓から富士山が[blank]。"}'::jsonb, '{"selected":"見られます"}'::jsonb, '見られます adalah bentuk potensial baku dari 見ます (dapat dilihat/disaksikan).', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 泳ぎます (berenang, Grup 1) ke bentuk potensial: 私は一キロぐらい___。', '{"options":["泳げます","泳ぎられます","泳ぎます","泳げります"],"translation":"Saya bisa berenang sekitar satu kilometer.","sentence_template":"私は一キロぐらい[blank]。"}'::jsonb, '{"selected":"泳げます"}'::jsonb, '泳ぎます (oyogimasu) -> ubah gi ke ge -> 泳げます (oyogemasu).', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kemampuan berbahasa: 辞書があれば、日本の新聞も少し___。', '{"options":["読めります","読めます","読みます","読まれます"],"translation":"Kalau ada kamus, saya juga bisa membaca koran Jepang sedikit.","sentence_template":"辞書があれば、日本の新聞も少し[blank]。"}'::jsonb, '{"selected":"読めます"}'::jsonb, '読みます (yomimasu) -> ubah mi ke me -> 読めます (yomemasu).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bisa memasak masakan Indonesia."', '{"display_text":"私はインドネシア料理が作れます。","romaji":"Watashi wa Indoneshia ryouri ga tsukuremasu.","phonetic_breakdown":["wa-ta-shi","wa","in-do-ne-shi-a","ryo-u-ri","ga","tsu-ku-re-ma-su"]}'::jsonb, '{"expected_transcript":"私はインドネシア料理が作れます。"}'::jsonb, '作ります (membuat) -> 作れます (bisa membuat/memasak).', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah di sini bisa menggunakan kartu transportasi IC?"', '{"display_text":"ここではICカードが使えますか。","romaji":"Koko de wa ai-shii kaado ga tsukaemasu ka.","phonetic_breakdown":["ko-ko","de","wa","a-i-shi-i","ka-a-do","ga","tsu-ka-e-ma-su","ka"]}'::jsonb, '{"expected_transcript":"ここではICカードが使えますか。"}'::jsonb, '使います (menggunakan) -> 使えます (bisa digunakan).', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena terlalu sibuk, hari ini saya tidak bisa istirahat."', '{"display_text":"忙しすぎて、今日は休めません。","romaji":"Isogashisugite, kyou wa yasumemasen.","phonetic_breakdown":["i-so-ga-shi-su-gi-te","kyo-u","wa","ya-su-me-ma-sen"]}'::jsonb, '{"expected_transcript":"忙しすぎて、今日は休めません。"}'::jsonb, '休みます -> 休めます -> 休めません (tidak bisa beristirahat).', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa mengendarai sepeda dan sepeda motor."', '{"tokens":["運転できます。","歩けます。","運転します。","バイクも","自転車も"],"target_translation":"Saya bisa mengendarai sepeda dan sepeda motor.","romaji":"Jitensha mo baiku mo unten dekimasu."}'::jsonb, '["自転車も","バイクも","運転できます。"]'::jsonb, '運転します (Grup 3) bentuk potensialnya adalah 運転できます.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Di perpustakaan ini kita bisa meminjam lima buku."', '{"tokens":["本が","借りられます。","貸せます。","借ります。","五冊","この図書館では"],"target_translation":"Di perpustakaan ini kita bisa meminjam lima buku.","romaji":"Kono toshokan de wa hon ga gosatsu kariraremasu."}'::jsonb, '["この図書館では","本が","五冊","借りられます。"]'::jsonb, '借ります (meminjam, Grup 2) -> 借りられます (bisa meminjam).', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena suaranya kecil, saya tidak bisa mendengar dengan baik."', '{"tokens":["聞けません。","聞きます。","声が小さいので、","話せません。","よく"],"target_translation":"Karena suaranya kecil, saya tidak bisa mendengar dengan baik.","romaji":"Koe ga chiisai node, yoku kikemasen."}'::jsonb, '["声が小さいので、","よく","聞けません。"]'::jsonb, '聞きます -> 聞けます -> 聞けません (tidak bisa mendengar/menyimak).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk potensial yang tepat untuk します (melakukan): 週末なら、残業が___。', '{"options":["しられます","せます","できます","しえます"],"translation":"Kalau akhir pekan, saya bisa lembur.","sentence_template":"週末なら、残業が[blank]。"}'::jsonb, '{"selected":"できます"}'::jsonb, 'します (Grup 3) memiliki bentuk potensial tidak beraturan: できます.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat mengenai pembelian tiket online: スマホで簡単に新幹線の切符が___。', '{"options":["買られます","買えります","買います","買えます"],"translation":"Dengan ponsel pintar kita bisa membeli tiket Shinkansen dengan mudah.","sentence_template":"スマホで簡単に新幹線の切符が[blank]。"}'::jsonb, '{"selected":"買えます"}'::jsonb, '買います (kaimasu) -> ubah i ke e -> 買えます (kaemasu).', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan di restoran. Mengapa tamu tidak memesan menu itu?', '{"audio_text":"すみません、私は豚肉が食べられないので、鶏肉の料理にします。","options":[{"id":"opt_1","text":"Karena porsinya terlalu kecil"},{"id":"opt_2","text":"Karena harganya terlalu mahal"},{"id":"opt_3","text":"Karena tamu tidak bisa makan daging babi dan memilih menu ayam"},{"id":"opt_4","text":"Karena menu daging babi sudah habis"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '豚肉が食べられない berarti tidak bisa makan daging babi; 鶏肉の料理にします memilih masakan ayam.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Kapan karyawan bisa mengambil cuti?', '{"audio_text":"入社して六か月たてば、有給休暇が取れます。","options":[{"id":"opt_1","text":"Langsung pada hari pertama masuk kerja"},{"id":"opt_2","text":"Setelah bekerja selama dua tahun"},{"id":"opt_3","text":"Hanya saat musim dingin"},{"id":"opt_4","text":"Setelah enam bulan bergabung di perusahaan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '六か月たてば有給休暇が取れます berarti setelah 6 bulan bisa mengambil cuti berbayar (yuukyuu kyuuka).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dari kantor saya bisa pulang ke asrama dengan berjalan kaki."', '{"tokens":["会社から","帰れます。","寮まで","帰ります。","歩いて","泳げます。"],"target_translation":"Dari kantor saya bisa pulang ke asrama dengan berjalan kaki.","romaji":"Kaisha kara ryou made aruite kaeremasu."}'::jsonb, '["会社から","寮まで","歩いて","帰れます。"]'::jsonb, '帰ります (Grup 1) -> 帰れます (bisa pulang).', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sekarang saya sudah bisa membaca peta kereta Jepang sendiri."', '{"display_text":"今は一人で日本の路線図が読めます。","romaji":"Ima wa hitori de Nihon no rosenzu ga yomemasu.","phonetic_breakdown":["i-ma","wa","hi-to-ri","de","ni-hon","no","ro-sen-zu","ga","yo-me-ma-su"]}'::jsonb, '{"expected_transcript":"今は一人で日本の路線図が読めます。"}'::jsonb, '路線図 (rosenzu) berarti peta jalur kereta; 読めます berarti bisa membaca.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata untuk ''rekan kerja'': 困ったとき、いつも___が助けてくれます。', '{"options":["同僚","財布","景色","季節"],"translation":"Saat kesulitan, rekan kerja selalu menolong saya.","sentence_template":"困ったとき、いつも[blank]が助けてくれます。"}'::jsonb, '{"selected":"同僚"}'::jsonb, '同僚 (douryou) berarti rekan kerja sejawat.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kata kerja yang berarti ''memperbaiki'': 先輩がパソコンのエラーを___してくれました。', '{"options":["散歩","修理","旅行","予約"],"translation":"Senior memperbaiki error komputer untuk saya.","sentence_template":"先輩がパソコンのエラーを[blank]してくれました。"}'::jsonb, '{"selected":"修理"}'::jsonb, '修理 (shuuri) berarti perbaikan; 修理する berarti memperbaiki.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan cerita karyawan baru ini. Siapa yang membantunya pindah rumah?', '{"audio_text":"引っ越しのとき、同じチームの先輩が荷物を運んでくれました。","options":[{"id":"opt_1","text":"Senior dari tim yang sama"},{"id":"opt_2","text":"Pemilik apartemen"},{"id":"opt_3","text":"Tetangga sebelah rumah"},{"id":"opt_4","text":"Adik laki-lakinya"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '同じチームの先輩 (onaji chiimu no senpai) berarti senior dari tim yang sama.', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Apa yang dilakukan Budi untuk temannya?', '{"audio_text":"道がわからないと言っていたので、駅まで案内してあげました。","options":[{"id":"opt_1","text":"Meminjamkan uang ongkos kereta"},{"id":"opt_2","text":"Mengantar dan memandu sampai stasiun"},{"id":"opt_3","text":"Membelikan peta kota"},{"id":"opt_4","text":"Memanggilkan taksi daring"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '案内する (annai suru) berarti memandu/menunjukkan jalan.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Rekan kerja mengajari saya cara membuat laporan."', '{"tokens":["教えて","同僚が","もらいました。","くれました。","あげました。","報告書の作り方を"],"target_translation":"Rekan kerja mengajari saya cara membuat laporan.","romaji":"Douryou ga houkokusho no tsukurikata o oshiete kuremashita."}'::jsonb, '["同僚が","報告書の作り方を","教えて","くれました。"]'::jsonb, 'Saat orang lain (同僚が) melakukan kebaikan untuk kita, gunakan ～てくれました.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih karena selalu membantu saya."', '{"display_text":"いつも手伝ってくれて、本当にありがとう。","romaji":"Itsumo tetsudatte kurete, hontou ni arigatou.","phonetic_breakdown":["i-tsu-mo","te-tsu-dat-te","ku-re-te","hon-to-u","ni","a-ri-ga-to-u"]}'::jsonb, '{"expected_transcript":"いつも手伝ってくれて、本当にありがとう。"}'::jsonb, '～てくれてありがとう adalah ungkapan terima kasih yang sangat natural kepada teman atau rekan akrab.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Saya membantu adik mengerjakan PR (saya -> orang lain): 私は弟の宿題を手伝って___。', '{"options":["いただきました","もらいました","あげました","くれました"],"translation":"Saya membantu mengerjakan PR adik saya.","sentence_template":"私は弟の宿題を手伝って[blank]。"}'::jsonb, '{"selected":"あげました"}'::jsonb, 'Jika pembicara (私は) memberi bantuan kepada orang lain, gunakan ～てあげます.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Teman meminjamkan payung kepada saya (orang lain -> saya): 雨が降っていたので、友達が傘を貸して___。', '{"options":["もらいました","あげました","やりました","くれました"],"translation":"Karena hujan turun, teman meminjamkan payung kepada saya.","sentence_template":"雨が降っていたので、友達が傘を貸して[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, 'Jika orang lain (友達が) melakukan kebaikan untuk pembicara, gunakan ～てくれます.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Saya menerima bantuan pemeriksaan laporan dari senior (私は ... に): 私は先輩にレポートをチェックして___。', '{"options":["もらいました","あげました","くれました","やりました"],"translation":"Saya dibantu senior memeriksa laporan.","sentence_template":"私は先輩にレポートをチェックして[blank]。"}'::jsonb, '{"selected":"もらいました"}'::jsonb, 'Saat subjeknya adalah penerima bantuan (私は) dan pemberinya ditandai に (先輩に), gunakan ～てもらいます.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya mengantar teman ke bandara dengan mobil."', '{"tokens":["くれました。","もらいました。","あげました。","私は","空港まで","送って","友達を"],"target_translation":"Saya mengantar teman ke bandara dengan mobil.","romaji":"Watashi wa tomodachi o kuukou made okutte agemashita."}'::jsonb, '["私は","友達を","空港まで","送って","あげました。"]'::jsonb, 'Pembicara memberi bantuan kepada teman -> 送ってあげました.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Senior membelikan saya kopi hangat."', '{"tokens":["買って","あげました。","温かいコーヒーを","もらいました。","くれました。","先輩が"],"target_translation":"Senior membelikan saya kopi hangat.","romaji":"Senpai ga atatakai koohii o katte kuremashita."}'::jsonb, '["先輩が","温かいコーヒーを","買って","くれました。"]'::jsonb, 'Subjek pemberi kebaikan kepada saya adalah 先輩が -> 買ってくれました.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya meminta teman Jepang memperbaiki bahasa Jepang saya."', '{"display_text":"日本人の友達に日本語を直してもらいました。","romaji":"Nihonjin no tomodachi ni Nihongo o naoshite moraimashita.","phonetic_breakdown":["ni-hon-jin","no","to-mo-da-chi","ni","ni-hon-go","o","na-o-shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"日本人の友達に日本語を直してもらいました。"}'::jsonb, '直します (memperbaiki/mengoreksi) + てもらいました berarti menerima bantuan koreksi dari teman.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan cerita ini. Siapa yang memasakkan bubur?', '{"audio_text":"昨日風邪を引いたとき、ルームメイトがおかゆを作ってくれました。","options":[{"id":"opt_1","text":"Pembicara memasak sendiri"},{"id":"opt_2","text":"Ibu pembicara yang memasak"},{"id":"opt_3","text":"Teman sekamar memasakkan bubur untuk pembicara"},{"id":"opt_4","text":"Dokter menyarankan membeli bubur"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'ルームメイトがおかゆを作ってくれました berarti teman sekamar membuatkan bubur untuk saya.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan kantor ini. Apa yang didapat pembicara dari Pak Suzuki?', '{"audio_text":"鈴木さんに新しいシフトの入力方法を教えてもらいました。","options":[{"id":"opt_1","text":"Hadiah ulang tahun"},{"id":"opt_2","text":"Pinjaman buku kamus"},{"id":"opt_3","text":"Jadwal cuti baru"},{"id":"opt_4","text":"Penjelasan cara input jadwal shift baru"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '鈴木さんに...教えてもらいました berarti saya diajari oleh Pak Suzuki.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan cerita berikut. Apa yang dilakukan pembicara untuk karyawan baru?', '{"audio_text":"新入社員が困っていたので、コピー機の使い方を説明してあげました。","options":[{"id":"opt_1","text":"Menjelaskan cara memakai mesin fotokopi kepada karyawan baru"},{"id":"opt_2","text":"Meminta karyawan baru memfotokopi dokumen"},{"id":"opt_3","text":"Memperbaiki mesin fotokopi yang macet"},{"id":"opt_4","text":"Membelikan kertas fotokopi baru"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '説明してあげました menunjukkan pembicara membantu menjelaskan kepada karyawan baru.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih partikel pemberi bantuan pada pola ～てもらいました: 私は田中さん___駅まで車で送ってもらいました。', '{"options":["が","に","で","を"],"translation":"Saya diantar oleh Pak Tanaka sampai stasiun dengan mobil.","sentence_template":"私は田中さん[blank]駅まで車で送ってもらいました。"}'::jsonb, '{"selected":"に"}'::jsonb, 'Pada pola ～てもらう, orang yang memberi bantuan ditandai dengan partikel に (atau から).', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih verba bantu yang tepat untuk subjek 友達が: 誕生日に友達がケーキを焼いて___。', '{"options":["あげました","やりました","くれました","もらいました"],"translation":"Pada hari ulang tahun saya, teman memanggangkan kue untuk saya.","sentence_template":"誕生日に友達がケーキを焼いて[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, '友達が (teman sebagai subjek yang berbuat baik kepada saya) wajib berpasangan dengan くれました.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat penawaran bantuan kepada junior: その荷物、重そうだね。僕が持って___よ。', '{"options":["くれる","もらう","いただく","あげる"],"translation":"Barang itu kelihatannya berat ya. Biar aku bawakan ya.","sentence_template":"その荷物、重そうだね。僕が持って[blank]よ。"}'::jsonb, '{"selected":"あげる"}'::jsonb, 'Subjek 僕が (aku) menawarkan bantuan kepada lawan bicara yang setara/lebih muda -> 持ってあげるよ.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya menerima bantuan dari senior untuk menerjemahkan dokumen ini."', '{"display_text":"先輩にこの書類を翻訳してもらいました。","romaji":"Senpai ni kono shorui o honyaku shite moraimashita.","phonetic_breakdown":["sen-pa-i","ni","ko-no","sho-ru-i","o","hon-ya-ku","shi-te","mo-ra-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先輩にこの書類を翻訳してもらいました。"}'::jsonb, '翻訳する (menerjemahkan) + てもらいました berarti dibantu menerjemahkan oleh senior.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ibu mengirimkan makanan Indonesia kepada saya."', '{"display_text":"母がインドネシアの食べ物を送ってくれました。","romaji":"Haha ga Indoneshia no tabemono o okutte kuremashita.","phonetic_breakdown":["ha-ha","ga","in-do-ne-shi-a","no","ta-be-mo-no","o","o-kut-te","ku-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"母がインドネシアの食べ物を送ってくれました。"}'::jsonb, '母が (ibu melakukan untuk saya) -> 送ってくれました.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya memotretkan foto untuk wisatawan itu."', '{"display_text":"私は観光客の写真を撮ってあげました。","romaji":"Watashi wa kankoukyaku no shashin o totte agemashita.","phonetic_breakdown":["wa-ta-shi","wa","kan-ko-u-kya-ku","no","sha-shin","o","tot-te","a-ge-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"私は観光客の写真を撮ってあげました。"}'::jsonb, '観光客 (kankoukyaku) berarti wisatawan; 撮ってあげました berarti saya mengambilkan foto untuk mereka.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya meminta teman mencarikan apartemen yang murah."', '{"tokens":["くれました。","あげました。","探して","友達に","もらいました。","安いアパートを"],"target_translation":"Saya meminta teman mencarikan apartemen yang murah.","romaji":"Tomodachi ni yasui apaato o sagashite moraimashita."}'::jsonb, '["友達に","安いアパートを","探して","もらいました。"]'::jsonb, '友達に (dari teman) + 探してもらいました (dibantu mencarikan).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Rekan kerja menggantikan shift saya hari Minggu."', '{"tokens":["くれました。","あげました。","日曜日のシフトを","もらいました。","同僚が","代わって"],"target_translation":"Rekan kerja menggantikan shift saya hari Minggu.","romaji":"Douryou ga nichiyoubi no shifuto o kawatte kuremashita."}'::jsonb, '["同僚が","日曜日のシフトを","代わって","くれました。"]'::jsonb, '代わります (menggantikan) -> 代わってくれました (rekan kerja berbaik hati menggantikan untuk saya).', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya membacakan buku cerita untuk anak kecil."', '{"tokens":["私は","くれました。","あげました。","読んで","もらいました。","子供に","絵本を"],"target_translation":"Saya membacakan buku cerita untuk anak kecil.","romaji":"Watashi wa kodomo ni ehon o yonde agemashita."}'::jsonb, '["私は","子供に","絵本を","読んで","あげました。"]'::jsonb, '絵本 (ehon) berarti buku bergambar; 私は...あげました berarti saya melakukan untuk anak tersebut.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat saat atasan/orang yang dihormati membantu kita (bentuk halus): 部長に仕事の相談に乗って___。', '{"options":["いただきました","やりました","あげました","くれましたか"],"translation":"Saya mendapat kesempatan berkonsultasi pekerjaan dengan Pak Manajer.","sentence_template":"部長に仕事の相談に乗って[blank]。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, '～ていただきました adalah bentuk merendah/sangat sopan dari ～てもらいました saat menerima bantuan dari atasan.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Bedakan subjek dengan cermat: 友達が vs 友達に: 私が道に迷ったとき、親切な人が地図を見せて___。', '{"options":["あげました","くれました","やりました","もらいました"],"translation":"Ketika saya tersesat, orang yang ramah menunjukkan peta kepada saya.","sentence_template":"私が道に迷ったとき、親切な人が地図を見せて[blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, 'Subjek pemberi kebaikan adalah 親切な人が (orang ramah itu) -> 見せてくれました.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Siapa yang memperbaiki sepeda Budi?', '{"audio_text":"自転車が壊れたので、近所の自転車屋さんに直してもらいました。","options":[{"id":"opt_1","text":"Teman sekamarnya"},{"id":"opt_2","text":"Bengkel sepeda di dekat rumahnya"},{"id":"opt_3","text":"Budi memperbaikinya sendiri"},{"id":"opt_4","text":"Senior di tempat kerjanya"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '近所の自転車屋さんに直してもらいました berarti diperbaiki oleh tukang/bengkel sepeda di dekat rumah.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan cerita ini. Mengapa pembicara merasa sangat terbantu?', '{"audio_text":"日本語の履歴書を書いたあと、先生が丁寧にチェックしてくれました。","options":[{"id":"opt_1","text":"Guru menuliskan CV-nya dari awal"},{"id":"opt_2","text":"Guru mengantarnya ke wawancara"},{"id":"opt_3","text":"Guru memeriksa CV bahasa Jepangnya dengan teliti"},{"id":"opt_4","text":"Guru meminjamkan jas wawancara"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '履歴書 (rirekisho) adalah CV/daftar riwayat hidup; 丁寧にチェックしてくれました berarti memeriksa dengan teliti.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya dibantu kakak mendaftar rekening bank."', '{"tokens":["手伝って","もらいました。","あげました。","手続きを","くれました。","兄に","銀行口座の"],"target_translation":"Saya dibantu kakak mendaftar rekening bank.","romaji":"Ani ni ginkou kouza no tetsuzuki o tetsudatte moraimashita."}'::jsonb, '["兄に","銀行口座の","手続きを","手伝って","もらいました。"]'::jsonb, '手続き (tetsuzuki) berarti prosedur/pengurusan; 兄に...手伝ってもらいました.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena teman sedang sibuk, saya membelikan makan siang untuknya."', '{"display_text":"友達が忙しそうだったので、昼ご飯を買ってあげました。","romaji":"Tomodachi ga isogashisou datta node, hirugohan o katte agemashita.","phonetic_breakdown":["to-mo-da-chi","ga","i-so-ga-shi-so-u","dat-ta","no-de","hi-ru-go-han","o","kat-te","a-ge-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"友達が忙しそうだったので、昼ご飯を買ってあげました。"}'::jsonb, '買ってあげました menekankan tindakan baik yang pembicara lakukan untuk temannya.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''demam'': 昨夜から三十八度の___があります。', '{"options":["風","雲","熱","音"],"translation":"Sejak semalam saya mengalami demam 38 derajat.","sentence_template":"昨夜から三十八度の[blank]があります。"}'::jsonb, '{"selected":"熱"}'::jsonb, '熱 (netsu) berarti demam atau panas tubuh; 熱がある berarti sedang demam.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata gejala flu: のどが痛くて、___も止まりません。', '{"options":["めがね","かさ","くつ","せき"],"translation":"Tenggorokan saya sakit dan batuk juga tidak berhenti.","sentence_template":"のどが痛くて、[blank]も止まりません。"}'::jsonb, '{"selected":"せき"}'::jsonb, 'せき (seki) berarti batuk; のどが痛い berarti sakit tenggorokan.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan keluhan pasien di klinik. Bagian tubuh mana yang sakit?', '{"audio_text":"朝からずっとお腹が痛いんです。昨日の夜、冷たいものを食べすぎました。","options":[{"id":"opt_1","text":"Kepala karena kurang tidur"},{"id":"opt_2","text":"Punggung karena mengangkat beban"},{"id":"opt_3","text":"Perut karena terlalu banyak makan makanan dingin"},{"id":"opt_4","text":"Gigi karena makan makanan manis"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'お腹が痛い (onaka ga itai) berarti sakit perut, akibat 冷たいものを食べすぎました.', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan arahan apoteker berikut. Kapan obat ini harus diminum?', '{"audio_text":"この薬は一日に三回、食事のあとで飲んでください。","options":[{"id":"opt_1","text":"Sekali sehari sebelum tidur"},{"id":"opt_2","text":"Dua kali sehari sebelum makan"},{"id":"opt_3","text":"Hanya saat demam tinggi"},{"id":"opt_4","text":"Tiga kali sehari setelah makan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '一日に三回、食事のあとで berarti tiga kali sehari setelah makan.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kondisi badan kurang sehat, saya pergi ke klinik."', '{"tokens":["体調が悪いので、","行きます。","会社へ","行きました。","病院へ"],"target_translation":"Karena kondisi badan kurang sehat, saya pergi ke klinik.","romaji":"Taichou ga warui node, byouin e ikimasu."}'::jsonb, '["体調が悪いので、","病院へ","行きます。"]'::jsonb, '体調が悪い (taichou ga warui) adalah ungkapan umum untuk kondisi badan sedang tidak fit.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan beristirahat cukup dan minum banyak air hangat."', '{"display_text":"ゆっくり休んで、温かい水をたくさん飲みます。","romaji":"Yukkuri yasunde, atatakai mizu o takusan nomimasu.","phonetic_breakdown":["yuk-ku-ri","ya-sun-de","a-ta-ta-ka-i","mi-zu","o","ta-ku-san","no-mi-ma-su"]}'::jsonb, '{"expected_transcript":"ゆっくり休んで、温かい水をたくさん飲みます。"}'::jsonb, 'ゆっくり休む (beristirahat tenang) dan 温かい水 (air hangat) sering dipakai saat membahas pemulihan kesehatan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat sebelum ほうがいい untuk saran positif: 熱が高いですから、早く病院へ___ほうがいいですよ。', '{"options":["行った","行きます","行く","行って"],"translation":"Karena demammu tinggi, sebaiknya segera pergi ke rumah sakit ya.","sentence_template":"熱が高いですから、早く病院へ[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"行った"}'::jsonb, 'Untuk saran positif ''sebaiknya melakukan'', gunakan [Verba Bentuk-TA] + ほうがいい -> 行ったほうがいい.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk saran negatif ''sebaiknya tidak melakukan'': 今夜はお酒を___ほうがいいですよ。', '{"options":["飲んで","飲まない","飲みます","飲んだ"],"translation":"Malam ini sebaiknya tidak minum alkohol ya.","sentence_template":"今夜はお酒を[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"飲まない"}'::jsonb, 'Untuk saran negatif ''sebaiknya tidak'', gunakan [Verba Bentuk-NAI] + ほうがいい -> 飲まないほうがいい.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 休みます (beristirahat) ke pola saran positif: 無理をしないで、今日は家で___ほうがいいです。', '{"options":["休んで","休み","休んだ","休む"],"translation":"Jangan memaksakan diri, hari ini sebaiknya beristirahat di rumah.","sentence_template":"無理をしないで、今日は家で[blank]ほうがいいです。"}'::jsonb, '{"selected":"休んだ"}'::jsonb, '休みます -> Bentuk TA: 休んだ + ほうがいいです.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya tidur lebih cepat setiap malam."', '{"tokens":["ほうが","寝た","寝て","いいです。","早く","寝る","毎晩"],"target_translation":"Sebaiknya tidur lebih cepat setiap malam.","romaji":"Maiban hayaku neta hou ga ii desu."}'::jsonb, '["毎晩","早く","寝た","ほうが","いいです。"]'::jsonb, '寝ます (Grup 2) -> Bentuk TA: 寝た + ほうがいいです.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena sedang flu, sebaiknya tidak mandi berendam terlalu lama."', '{"tokens":["長く","入った","風邪ですから、","入らない","ほうがいいです。","入ります","お風呂に"],"target_translation":"Karena sedang flu, sebaiknya tidak mandi berendam terlalu lama.","romaji":"Kaze desu kara, nagaku ofuro ni hairanai hou ga ii desu."}'::jsonb, '["風邪ですから、","長く","お風呂に","入らない","ほうがいいです。"]'::jsonb, 'Saran larangan halus memakai bentuk NAI: 入らないほうがいいです.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya kamu segera minum obat ini."', '{"display_text":"すぐにこの薬を飲んだほうがいいですよ。","romaji":"Sugu ni kono kusuri o nonda hou ga ii desu yo.","phonetic_breakdown":["su-gu","ni","ko-no","ku-su-ri","o","non-da","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"すぐにこの薬を飲んだほうがいいですよ。"}'::jsonb, '飲みます -> 飲んだ + ほうがいいですよ memberikan saran yang hangat dan peduli.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan saran dokter ini. Apa yang sebaiknya dilakukan pasien?', '{"audio_text":"二、三日は激しい運動をしないで、よく寝たほうがいいですよ。","options":[{"id":"opt_1","text":"Tidak berolahraga berat dan banyak tidur selama dua hingga tiga hari"},{"id":"opt_2","text":"Berlari pagi setiap hari agar berkeringat"},{"id":"opt_3","text":"Langsung kembali lembur di kantor"},{"id":"opt_4","text":"Menghentikan semua obat setelah satu hari"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '激しい運動をしないで、よく寝たほうがいい menyarankan menghindari olahraga berat dan tidur cukup.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan nasihat senior ini. Apa sarannya sebelum musim dingin tiba?', '{"audio_text":"来月から急に寒くなりますから、暖かいコートを買っておいたほうがいいですよ。","options":[{"id":"opt_1","text":"Menyalakan kipas angin di kamar"},{"id":"opt_2","text":"Membeli mantel hangat sebelum bulan depan mendadak dingin"},{"id":"opt_3","text":"Membuka jendela setiap malam"},{"id":"opt_4","text":"Pindah ke apartemen yang lebih kecil"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '暖かいコートを買っておいたほうがいい menyarankan membeli mantel hangat sebagai persiapan.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Mengapa dia menyarankan naik kereta?', '{"audio_text":"夕方は道路がとても混みますから、バスより電車で行ったほうがいいですよ。","options":[{"id":"opt_1","text":"Karena tiket bus sudah habis"},{"id":"opt_2","text":"Karena stasiun kereta sangat jauh"},{"id":"opt_3","text":"Karena jalanan sangat macet pada sore hari"},{"id":"opt_4","text":"Karena bus tidak beroperasi pada hari kerja"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '道路がとても混みますから (karena jalanan sangat macet) menjadi alasan saran naik kereta.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi saran saat mata lelah menatap layar: パソコンを長く見すぎたら、少し目を___ほうがいいです。', '{"options":["休めない","休めて","休める","休めた"],"translation":"Kalau terlalu lama menatap komputer, sebaiknya mengistirahatkan mata sebentar.","sentence_template":"パソコンを長く見すぎたら、少し目を[blank]ほうがいいです。"}'::jsonb, '{"selected":"休めた"}'::jsonb, '休めます (mengistirahatkan, transitif) -> Bentuk TA: 休めた + ほうがいいです.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih saran negatif yang tepat untuk makanan pedas saat sakit perut: 胃が痛いときは、辛い物を___ほうがいいですよ。', '{"options":["食べない","食べます","食べた","食べて"],"translation":"Saat lambung sakit, sebaiknya tidak makan makanan pedas ya.","sentence_template":"胃が痛いときは、辛い物を[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"食べない"}'::jsonb, 'Saran menghindari sesuatu menggunakan bentuk NAI: 食べないほうがいい.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi saran menghadapi ujian JLPT: 毎日少しずつ漢字を___ほうがいいです。', '{"options":["覚える","覚えた","覚えます","覚えて"],"translation":"Sebaiknya menghafal kanji sedikit demi sedikit setiap hari.","sentence_template":"毎日少しずつ漢字を[blank]ほうがいいです。"}'::jsonb, '{"selected":"覚えた"}'::jsonb, '覚えます (menghafal) -> Bentuk TA: 覚えた + ほうがいいです.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena di luar hujan, sebaiknya membawa payung."', '{"display_text":"外は雨ですから、傘を持って行ったほうがいいですよ。","romaji":"Soto wa ame desu kara, kasa o motte itta hou ga ii desu yo.","phonetic_breakdown":["so-to","wa","a-me","de-su","ka-ra","ka-sa","o","mot-te","it-ta","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"外は雨ですから、傘を持って行ったほうがいいですよ。"}'::jsonb, '持って行きます (membawa pergi) -> 持って行った + ほうがいいですよ.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya mencatat hal penting di buku catatan."', '{"display_text":"大事なことはメモに書いたほうがいいです。","romaji":"Daiji na koto wa memo ni kaita hou ga ii desu.","phonetic_breakdown":["da-i-ji","na","ko-to","wa","me-mo","ni","ka-i-ta","ho-u","ga","i-i","de-su"]}'::jsonb, '{"expected_transcript":"大事なことはメモに書いたほうがいいです。"}'::jsonb, '書きます -> 書いた + ほうがいいです adalah nasihat kerja yang sangat umum di Jepang.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya tidak minum kopi terlalu malam."', '{"display_text":"夜遅くコーヒーを飲まないほうがいいですよ。","romaji":"Yoru osoku koohii o nomanai hou ga ii desu yo.","phonetic_breakdown":["yo-ru","o-so-ku","ko-o-hi-i","o","no-ma-na-i","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"夜遅くコーヒーを飲まないほうがいいですよ。"}'::jsonb, '飲みます -> 飲まない + ほうがいいですよ menyarankan agar tidak minum kopi larut malam.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya segera menghubungi atasan jika terjadi masalah."', '{"tokens":["報告して","報告した","ほうがいいです。","すぐ上司に","報告する","問題があったら、"],"target_translation":"Sebaiknya segera menghubungi atasan jika terjadi masalah.","romaji":"Mondai ga attara, sugu joushi ni houkoku shita hou ga ii desu."}'::jsonb, '["問題があったら、","すぐ上司に","報告した","ほうがいいです。"]'::jsonb, '報告します (melapor) -> Bentuk TA: 報告した + ほうがいいです.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya tidak memaksakan diri saat demam."', '{"tokens":["熱があるときは、","します","ほうがいいです。","無理を","しない","した"],"target_translation":"Sebaiknya tidak memaksakan diri saat demam.","romaji":"Netsu ga aru toki wa, muri o shinai hou ga ii desu."}'::jsonb, '["熱があるときは、","無理を","しない","ほうがいいです。"]'::jsonb, '無理をします (memaksakan diri) -> bentuk NAI: 無理をしない + ほうがいいです.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya berangkat tiga puluh menit lebih awal."', '{"tokens":["三十分","早く","出発して","出発する","ほうがいいですよ。","出発した"],"target_translation":"Sebaiknya berangkat tiga puluh menit lebih awal.","romaji":"Sanjuppun hayaku shuppatsu shita hou ga ii desu yo."}'::jsonb, '["三十分","早く","出発した","ほうがいいですよ。"]'::jsonb, '出発します (berangkat) -> 出発した + ほうがいいですよ.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk saran positif yang tepat dari 聞きます (bertanya): わからないことは先輩に___ほうがいいですよ。', '{"options":["聞いて","聞きます","聞いた","聞く"],"translation":"Hal yang tidak kamu pahami sebaiknya ditanyakan kepada senior ya.","sentence_template":"わからないことは先輩に[blank]ほうがいいですよ。"}'::jsonb, '{"selected":"聞いた"}'::jsonb, '聞きます -> Bentuk TA: 聞いた + ほうがいいですよ.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih saran larangan yang tepat untuk merokok di dalam ruangan: 健康のために、たばこは___ほうがいいです。', '{"options":["吸った","吸います","吸って","吸わない"],"translation":"Demi kesehatan, sebaiknya tidak merokok.","sentence_template":"健康のために、たばこは[blank]ほうがいいです。"}'::jsonb, '{"selected":"吸わない"}'::jsonb, '吸います (menghisap rokok) -> Bentuk NAI: 吸わない + ほうがいいです.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Apa saran teman mengenai reservasi restoran?', '{"audio_text":"そのレストランは週末とても人気がありますから、先に予約したほうがいいですよ。","options":[{"id":"opt_1","text":"Datang langsung tanpa reservasi"},{"id":"opt_2","text":"Pergi pada tengah malam saja"},{"id":"opt_3","text":"Mencari restoran lain yang lebih mahal"},{"id":"opt_4","text":"Membuat reservasi lebih dulu karena sangat ramai saat akhir pekan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '先に予約したほうがいい menyarankan memesan tempat lebih dulu.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan saran perawat di puskesmas. Apa yang harus dihindari pasien hari ini?', '{"audio_text":"予防接種のあとは、今日はお風呂に入らないで、シャワーだけにしたほうがいいです。","options":[{"id":"opt_1","text":"Menghindari berendam di bak mandi dan cukup mandi pancuran saja"},{"id":"opt_2","text":"Tidak boleh minum air putih sepanjang hari"},{"id":"opt_3","text":"Harus tidur tanpa selimut"},{"id":"opt_4","text":"Tidak boleh makan nasi selama dua hari"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お風呂に入らないで、シャワーだけにしたほうがいい menyarankan hanya mandi shower setelah vaksinasi.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebaiknya memeriksa ramalan cuaca sebelum bepergian."', '{"tokens":["出かける前に、","天気予報を","見て","見る","見た","ほうがいいです。"],"target_translation":"Sebaiknya memeriksa ramalan cuaca sebelum bepergian.","romaji":"Dekakeru mae ni, tenkiyohou o mita hou ga ii desu."}'::jsonb, '["出かける前に、","天気予報を","見た","ほうがいいです。"]'::jsonb, '天気予報 (tenkiyohou) adalah ramalan cuaca; 見ます -> 見た + ほうがいいです.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika tenggorokan sakit, sebaiknya banyak minum minuman hangat."', '{"display_text":"のどが痛いなら、温かい飲み物を飲んだほうがいいですよ。","romaji":"Nodo ga itai nara, atatakai nomimono o nonda hou ga ii desu yo.","phonetic_breakdown":["no-do","ga","i-ta-i","na-ra","a-ta-ta-ka-i","no-mi-mo-no","o","non-da","ho-u","ga","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"のどが痛いなら、温かい飲み物を飲んだほうがいいですよ。"}'::jsonb, 'Kombinasi 痛いなら + 飲んだほうがいいですよ terdengar sangat alami saat memberi nasihat kepada rekan.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''pulang lebih awal (izin)'': 具合が悪いので、今日は___させていただきます。', '{"options":["早退","歓迎","旅行","出張"],"translation":"Karena badan kurang sehat, hari ini saya mohon izin pulang lebih awal.","sentence_template":"具合が悪いので、今日は[blank]させていただきます。"}'::jsonb, '{"selected":"早退"}'::jsonb, '早退 (soutai) berarti pulang lebih awal dari jam kerja atau sekolah karena suatu keperluan/sakit.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata gangguan kereta api: 事故で電車が二十分___しています。', '{"options":["買い物","遅延","運動","料理"],"translation":"Karena kecelakaan, kereta mengalami keterlambatan dua puluh menit.","sentence_template":"事故で電車が二十分[blank]しています。"}'::jsonb, '{"selected":"遅延"}'::jsonb, '遅延 (chien) berarti keterlambatan jadwal transportasi umum.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan telepon karyawan ini. Mengapa ia tidak bisa hadir di kantor?', '{"audio_text":"すみません、朝から熱があるので、今日は会社を休ませていただけますか。","options":[{"id":"opt_1","text":"Keretanya mogok di stasiun"},{"id":"opt_2","text":"Ia demam sejak pagi sehingga meminta izin tidak masuk"},{"id":"opt_3","text":"Ia lupa membawa kartu akses kantor"},{"id":"opt_4","text":"Ia harus menemani tamu dari Indonesia"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '熱があるので (karena demam) + 休ませていただけますか (bolehkah saya izin libur).', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di stasiun. Mengapa jalur kereta dihentikan sementara?', '{"audio_text":"台風が近づいているので、午後の特急電車は運休になります。","options":[{"id":"opt_1","text":"Karena ada perbaikan rel mendadak"},{"id":"opt_2","text":"Karena listrik di stasiun padam"},{"id":"opt_3","text":"Karena topan sedang mendekat sehingga kereta ekspres sore dibatalkan"},{"id":"opt_4","text":"Karena jumlah penumpang terlalu sedikit"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '台風が近づいているので (karena topan mendekat) + 運休 (dibatalkan operasinya).', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Karena jalanan macet, busnya datang terlambat."', '{"tokens":["混んでいたので、","道が","バスが","混んでいました。","早かったです。","遅れました。"],"target_translation":"Karena jalanan macet, busnya datang terlambat.","romaji":"Michi ga konde ita node, basu ga okuremashita."}'::jsonb, '["道が","混んでいたので、","バスが","遅れました。"]'::jsonb, '混んでいたので menyatakan penyebab keterlambatan secara objektif dan sopan.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ada urusan keluarga, besok saya mohon izin cuti."', '{"display_text":"家族の用事があるので、明日休みをいただきたいです。","romaji":"Kazoku no youji ga aru node, ashita yasumi o itadakitai desu.","phonetic_breakdown":["ka-zo-ku","no","yo-u-ji","ga","a-ru","no-de","a-shi-ta","ya-su-mi","o","i-ta-da-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"家族の用事があるので、明日休みをいただきたいです。"}'::jsonb, '用事 (youji) berarti keperluan/urusan; ～ので sangat cocok dipakai saat mengajukan izin kepada atasan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Sambungkan Nomina 雨 (hujan) dengan ので secara tepat: 今日は___ので、屋外の作業は中止です。', '{"options":["雨の","雨い","雨な","雨だ"],"translation":"Karena hari ini hujan, pekerjaan di luar ruangan dibatalkan.","sentence_template":"今日は[blank]ので、屋外の作業は中止です。"}'::jsonb, '{"selected":"雨な"}'::jsonb, 'Aturan penting N4: Nomina dan Adjektiva-NA wajib memakai な sebelum ので -> 雨なので (bukan 雨だので).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Sambungkan Adjektiva-NA 静か (tenang) dengan ので: この図書館は___ので、勉強しやすいです。', '{"options":["静かの","静かだ","静かい","静かな"],"translation":"Karena perpustakaan ini tenang, nyaman untuk belajar.","sentence_template":"この図書館は[blank]ので、勉強しやすいです。"}'::jsonb, '{"selected":"静かな"}'::jsonb, 'Adjektiva-NA (静か) membutuhkan な sebelum ので -> 静かなので.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Sambungkan Adjektiva-I (sibuk) dengan ので secara tepat: 今週はとても___ので、週末も出勤します。', '{"options":["忙しい","忙しく","忙しだ","忙しいな"],"translation":"Karena minggu ini sangat sibuk, akhir pekan pun saya masuk kerja.","sentence_template":"今週はとても[blank]ので、週末も出勤します。"}'::jsonb, '{"selected":"忙しい"}'::jsonb, 'Adjektiva-I langsung diikuti ので tanpa な -> 忙しいので.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta terlambat, saya terlambat datang ke rapat."', '{"tokens":["遅刻しました。","電車が","遅れました。","早退しました。","会議に","遅れたので、"],"target_translation":"Karena kereta terlambat, saya terlambat datang ke rapat.","romaji":"Densha ga okureta node, kaigi ni chikoku shimashita."}'::jsonb, '["電車が","遅れたので、","会議に","遅刻しました。"]'::jsonb, 'Verba bentuk biasa (遅れた) langsung disambungkan dengan ので.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena tempat ini dekat dari stasiun, sangat praktis."', '{"tokens":["近いので、","駅から","遠いです。","便利です。","とても","近いなので、"],"target_translation":"Karena tempat ini dekat dari stasiun, sangat praktis.","romaji":"Eki kara chikai node, totemo benri desu."}'::jsonb, '["駅から","近いので、","とても","便利です。"]'::jsonb, '近い adalah Adjektiva-I, jadi langsung 近いので (tanpa な).', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena besok ada ujian, malam ini saya harus belajar."', '{"display_text":"明日は試験があるので、今夜は勉強しなければなりません。","romaji":"Ashita wa shiken ga aru node, konya wa benkyou shinakereba narimasen.","phonetic_breakdown":["a-shi-ta","wa","shi-ken","ga","a-ru","no-de","kon-ya","wa","ben-kyo-u","shi-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"明日は試験があるので、今夜は勉強しなければなりません。"}'::jsonb, 'ある (bentuk kamus) + ので menyatakan alasan secara halus dan objektif.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan staf toko. Mengapa toko tutup lebih awal hari ini?', '{"audio_text":"本日は棚卸し作業があるので、午後六時に閉店いたします。","options":[{"id":"opt_1","text":"Karena sedang renovasi gedung"},{"id":"opt_2","text":"Karena listrik di area toko padam"},{"id":"opt_3","text":"Karena ada libur nasional"},{"id":"opt_4","text":"Karena ada kegiatan stok opname sehingga tutup jam enam sore"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '棚卸し作業 (tanaoroshi sagyou) adalah pemeriksaan stok/inventaris, dan 閉店いたします berarti tutup toko.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan suara dari rekan kerja. Mengapa ia meminta tolong?', '{"audio_text":"パソコンが急に動かなくなったので、IT担当の方を呼んでいただけませんか。","options":[{"id":"opt_1","text":"Komputernya mendadak tidak berfungsi sehingga ia minta dipanggilkan staf IT"},{"id":"opt_2","text":"Ia lupa kata sandi email perusahaan"},{"id":"opt_3","text":"Printernya kehabisan kertas"},{"id":"opt_4","text":"Ia ingin membeli komputer baru"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '動かなくなったので berarti karena mendadak tidak bisa beroperasi/macet.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang tunggu. Mengapa pasien diminta menunggu?', '{"audio_text":"ただいま大変混み合っておりますので、三十分ほどお待ちください。","options":[{"id":"opt_1","text":"Karena dokter sedang keluar makan siang"},{"id":"opt_2","text":"Karena saat ini sedang sangat ramai sehingga diminta menunggu sekitar 30 menit"},{"id":"opt_3","text":"Karena mesin pendaftaran rusak"},{"id":"opt_4","text":"Karena klinik akan segera tutup"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '混み合っておりますので adalah bentuk sangat sopan dari 混んでいるので (karena sedang ramai).', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk sambung yang benar untuk Nomina 日曜日: 明日は___ので、銀行は閉まっています。', '{"options":["日曜だ","日曜な","日曜に","日曜の"],"translation":"Karena besok hari Minggu, bank tutup.","sentence_template":"明日は[blank]ので、銀行は閉まっています。"}'::jsonb, '{"selected":"日曜な"}'::jsonb, 'Nomina (日曜) diikuti な sebelum ので -> 日曜なので.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi alasan sopan menggunakan bentuk lampau negatif: 説明書がよく___ので、先輩に質問しました。', '{"options":["わかりませんだ","わからないな","わからなかった","わからなくて"],"translation":"Karena saya kurang memahami buku panduan, saya bertanya kepada senior.","sentence_template":"説明書がよく[blank]ので、先輩に質問しました。"}'::jsonb, '{"selected":"わからなかった"}'::jsonb, 'Bentuk biasa lampau negatif わからなかった langsung disambung ので -> わからなかったので.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih alasan yang tepat untuk kalimat permintaan izin: 少し頭が___ので、休憩室で休んでもいいですか。', '{"options":["痛く","痛いな","痛いだ","痛い"],"translation":"Karena kepala saya agak sakit, bolehkah saya beristirahat di ruang istirahat?","sentence_template":"少し頭が[blank]ので、休憩室で休んでもいいですか。"}'::jsonb, '{"selected":"痛い"}'::jsonb, '痛い adalah Adjektiva-I, langsung menjadi 痛いので.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masih baru pertama kali, tolong bimbing saya."', '{"display_text":"初めてなので、どうぞよろしくお願いします。","romaji":"Hajimete na node, douzo yoroshiku onegai shimasu.","phonetic_breakdown":["ha-ji-me-te","na","no-de","do-u-zo","yo-ro-shi-ku","o-ne-ga-i","shi-ma-su"]}'::jsonb, '{"expected_transcript":"初めてなので、どうぞよろしくお願いします。"}'::jsonb, '初めて (pertama kali) berperilaku seperti nomina/na-adj, sehingga memakai なので -> 初めてなので.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak sempat sarapan, sekarang saya sangat lapar."', '{"display_text":"朝ご飯を食べなかったので、今とてもお腹が空いています。","romaji":"Asagohan o tabenakatta node, ima totemo onaka ga suite imasu.","phonetic_breakdown":["a-sa-go-han","o","ta-be-na-kat-ta","no-de","i-ma","to-te-mo","o-na-ka","ga","su-i-te","i-ma-su"]}'::jsonb, '{"expected_transcript":"朝ご飯を食べなかったので、今とてもお腹が空いています。"}'::jsonb, '食べなかった (tidak makan, lampau biasa) + ので.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena suaranya kurang terdengar, tolong keraskan sedikit."', '{"display_text":"少し聞こえにくいので、もう少し大きく話してください。","romaji":"Sukoshi kikoenikui node, mou sukoshi ookiku hanashite kudasai.","phonetic_breakdown":["su-ko-shi","ki-ko-e-ni-ku-i","no-de","mo-u","su-ko-shi","o-o-ki-ku","ha-na-shi-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"少し聞こえにくいので、もう少し大きく話してください。"}'::jsonb, '聞こえにくい (sulit terdengar) berakhiran い sehingga langsung diikuti ので.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena ruangannya panas, saya membuka jendela."', '{"tokens":["窓を","閉めました。","暑いので、","部屋が","暑いなので、","開けました。"],"target_translation":"Karena ruangannya panas, saya membuka jendela.","romaji":"Heya ga atsui node, mado o akemashita."}'::jsonb, '["部屋が","暑いので、","窓を","開けました。"]'::jsonb, '暑い (Adjektiva-I) + ので + 窓を開けました.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena saya suka masakan Jepang, saya sering memasak ramen."', '{"tokens":["日本料理が","好きなので、","よくラーメンを","嫌いです。","好きだので、","作ります。"],"target_translation":"Karena saya suka masakan Jepang, saya sering memasak ramen.","romaji":"Nihon ryouri ga suki na node, yoku raamen o tsukurimasu."}'::jsonb, '["日本料理が","好きなので、","よくラーメンを","作ります。"]'::jsonb, '好き adalah Adjektiva-NA, sehingga wajib memakai な sebelum ので -> 好きなので.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah jam lima, mari kita selesaikan pekerjaan hari ini."', '{"tokens":["今日の仕事を","なので、","終わりにしましょう。","始めましょう。","もう五時","だので、"],"target_translation":"Karena sudah jam lima, mari kita selesaikan pekerjaan hari ini.","romaji":"Mou goji na node, kyou no shigoto o owari ni shimashou."}'::jsonb, '["もう五時","なので、","今日の仕事を","終わりにしましょう。"]'::jsonb, '五時 adalah Nomina, jadi memakai なので.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih sambungan yang tepat untuk bentuk sopan dengan ので: これから会議が始まり___ので、携帯電話の電源をお切りください。', '{"options":["ます","ますな","ますだ","まして"],"translation":"Karena rapat akan segera dimulai, mohon matikan daya ponsel Anda.","sentence_template":"これから会議が始まり[blank]ので、携帯電話の電源をお切りください。"}'::jsonb, '{"selected":"ます"}'::jsonb, 'Dalam pengumuman resmi/sangat sopan, ～ますので boleh digunakan langsung tanpa な atau だ.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kalimat yang paling tepat untuk Nomina 外国人: 私は___ので、まだ日本の習慣をよく知りません。', '{"options":["外国人の","外国人な","外国人だ","外国人に"],"translation":"Karena saya orang asing, saya belum terlalu tahu kebiasaan Jepang.","sentence_template":"私は[blank]ので、まだ日本の習慣をよく知りません。"}'::jsonb, '{"selected":"外国人な"}'::jsonb, 'Nomina 外国人 + なので adalah bentuk baku yang tepat.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan ini. Mengapa pembicara tidak bisa ikut lembur hari ini?', '{"audio_text":"申し訳ありません、今夜は市役所から届いた書類の手続きがあるので、定時で失礼します。","options":[{"id":"opt_1","text":"Ia harus menemui dokter gigi"},{"id":"opt_2","text":"Ia sudah berjanji makan malam dengan teman"},{"id":"opt_3","text":"Ia harus mengurus dokumen dari balai kota sehingga pulang tepat waktu"},{"id":"opt_4","text":"Ia merasa terlalu lelah bekerja"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '定時で失礼します berarti pamit pulang tepat waktu sesuai jam kerja.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan resepsionis. Mengapa tamu diminta menunggu di lobi?', '{"audio_text":"ただいま担当者が別の会議に出ておりますので、ロビーで少々お待ちください。","options":[{"id":"opt_1","text":"Karena staf penanggung jawab sedang cuti"},{"id":"opt_2","text":"Karena ruang pertemuan sedang dibersihkan"},{"id":"opt_3","text":"Karena tamu datang terlalu cepat satu jam"},{"id":"opt_4","text":"Karena staf penanggung jawab sedang mengikuti rapat lain"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '別の会議に出ておりますので berarti karena sedang berada di rapat lain.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena hujan turun dengan deras, saya pulang naik taksi."', '{"tokens":["タクシーで","降っています。","雨が","歩いて","帰ります。","ひどく降っているので、"],"target_translation":"Karena hujan turun dengan deras, saya pulang naik taksi.","romaji":"Ame ga hidoku futte iru node, takushii de kaerimasu."}'::jsonb, '["雨が","ひどく降っているので、","タクシーで","帰ります。"]'::jsonb, 'ひどく降っている (turun deras) + ので menyatakan penyebab objektif.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masih ada waktu, mari kita periksa dokumen ini sekali lagi."', '{"display_text":"まだ時間があるので、もう一度この資料を確認しましょう。","romaji":"Mada jikan ga aru node, mou ichido kono shiryou o kakunin shimashou.","phonetic_breakdown":["ma-da","ji-kan","ga","a-ru","no-de","mo-u","i-chi-do","ko-no","shi-ryo-u","o","ka-ku-nin","shi-ma-sho-u"]}'::jsonb, '{"expected_transcript":"まだ時間があるので、もう一度この資料を確認しましょう。"}'::jsonb, '時間があるので + 確認しましょう sangat natural dipakai saat kerja tim di kantor.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang berarti ''hujan berhenti / reda'': 雨が___、外へ散歩に行きましょう。', '{"options":["食べたら","読んだら","やんだら","書いたら"],"translation":"Kalau hujan sudah reda, mari kita pergi jalan-jalan ke luar.","sentence_template":"雨が[blank]、外へ散歩に行きましょう。"}'::jsonb, '{"selected":"やんだら"}'::jsonb, '雨がやみます berarti hujan berhenti/reda -> bentuk たら: やんだら.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata rencana akhir pekan: 今度の___に友達と京都へ旅行します。', '{"options":["残業","遅刻","欠席","連休"],"translation":"Pada libur panjang nanti, saya akan berwisata ke Kyoto bersama teman.","sentence_template":"今度の[blank]に友達と京都へ旅行します。"}'::jsonb, '{"selected":"連休"}'::jsonb, '連休 (renkyuu) berarti hari libur berturut-turut / libur panjang.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja ini. Apa yang akan mereka lakukan kalau hari Minggu cerah?', '{"audio_text":"日曜日、天気がよかったら、みんなで公園でバーベキューをしませんか。","options":[{"id":"opt_1","text":"Mengadakan barbekyu bersama di taman"},{"id":"opt_2","text":"Menonton film di bioskop"},{"id":"opt_3","text":"Belajar bahasa Jepang di perpustakaan"},{"id":"opt_4","text":"Berbelanja di pusat perbelanjaan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '天気がよかったら (kalau cuacanya bagus) + 公園でバーベキュー (barbekyu di taman).', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan instruksi kerja ini. Apa yang harus dilakukan setelah selesai membersihkan mesin?', '{"audio_text":"機械の掃除が終わったら、スイッチを切って報告してください。","options":[{"id":"opt_1","text":"Langsung pulang tanpa melapor"},{"id":"opt_2","text":"Mematikan sakelar dan melapor setelah pembersihan selesai"},{"id":"opt_3","text":"Menyalakan mesin kembali selama lima menit"},{"id":"opt_4","text":"Memindahkan mesin ke gudang"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '掃除が終わったら (setelah bersih-bersih selesai) + スイッチを切って報告 (matikan sakelar dan lapor).', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah sampai di stasiun, tolong telepon saya."', '{"tokens":["電話を","着きます、","駅に","ください。","着いたら、","食べたら、"],"target_translation":"Kalau sudah sampai di stasiun, tolong telepon saya.","romaji":"Eki ni tsuitara, denwa o kudasai."}'::jsonb, '["駅に","着いたら、","電話を","ください。"]'::jsonb, '着きます (tiba) -> Bentuk TA: 着いた + ら = 着いたら (jika/setelah tiba).', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada waktu luang, saya ingin pergi ke pemandian air panas."', '{"display_text":"時間があったら、温泉へ行きたいです。","romaji":"Jikan ga attara, onsen e ikitai desu.","phonetic_breakdown":["ji-kan","ga","at-ta-ra","on-sen","e","i-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"時間があったら、温泉へ行きたいです。"}'::jsonb, 'あります -> あった + ら = あったら (kalau ada).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah Adjektiva-I 安い (murah) ke bentuk ～たら: このパソコンがもっと___、買いたいです。', '{"options":["安かったら","安いったら","安くだったら","安いたら"],"translation":"Kalau komputer ini lebih murah, saya ingin membelinya.","sentence_template":"このパソコンがもっと[blank]、買いたいです。"}'::jsonb, '{"selected":"安かったら"}'::jsonb, 'Adjektiva-I diubah ke bentuk lampau biasa (安かった) lalu ditambah ら -> 安かったら.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah Adjektiva-NA 暇 (senggang) ke bentuk ～たら: 明日___、映画を見に行きませんか。', '{"options":["暇ならたら","暇だったら","暇いったら","暇かったら"],"translation":"Kalau besok senggang, maukah pergi menonton film?","sentence_template":"明日[blank]、映画を見に行きませんか。"}'::jsonb, '{"selected":"暇だったら"}'::jsonb, 'Nomina dan Adjektiva-NA memakai だった + ら -> 暇だったら.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah bentuk negatif わからない (tidak tahu) ke ～たら: やり方が___、いつでも聞いてくださいね。', '{"options":["わかりませんでしたら","わからなくてら","わからなかったら","わからないたら"],"translation":"Kalau tidak tahu caranya, silakan bertanya kapan saja ya.","sentence_template":"やり方が[blank]、いつでも聞いてくださいね。"}'::jsonb, '{"selected":"わからなかったら"}'::jsonb, 'Bentuk NAI (わからない) -> lampau negatif (わからなかった) + ら = わからなかったら.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau besok hujan, pertandingan akan dibatalkan."', '{"tokens":["雨かったら、","始まります。","中止になります。","雨だったら、","明日","試合は"],"target_translation":"Kalau besok hujan, pertandingan akan dibatalkan.","romaji":"Ashita ame dattara, shiai wa chuushi ni narimasu."}'::jsonb, '["明日","雨だったら、","試合は","中止になります。"]'::jsonb, '雨 (Nomina) + だったら membentuk pengandaian ''kalau hujan''.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah pekerjaan ini selesai, mari kita istirahat."', '{"tokens":["始まったら、","終わります、","終わったら、","この仕事が","休憩しましょう。"],"target_translation":"Setelah pekerjaan ini selesai, mari kita istirahat.","romaji":"Kono shigoto ga owattara, kyuukei shimashou."}'::jsonb, '["この仕事が","終わったら、","休憩しましょう。"]'::jsonb, '終わります -> 終わった + ら = 終わったら menyatakan ''setelah selesai''.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah sampai di rumah, kirimkan pesan ya."', '{"display_text":"家に着いたら、メッセージを送ってくださいね。","romaji":"Ie ni tsuitara, messeeji o okutte kudasai ne.","phonetic_breakdown":["i-e","ni","tsu-i-ta-ra","mes-se-e-ji","o","o-kut-te","ku-da-sa-i","ne"]}'::jsonb, '{"expected_transcript":"家に着いたら、メッセージを送ってくださいね。"}'::jsonb, '着いたら sangat umum dipakai untuk memastikan teman atau keluarga sudah tiba dengan selamat.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan di pabrik. Apa yang dilakukan jika lampu merah menyala?', '{"audio_text":"もし赤いランプがついたら、すぐに機械を止めて責任者を呼んでください。","options":[{"id":"opt_1","text":"Membiarkan mesin berjalan sampai jam istirahat"},{"id":"opt_2","text":"Mencabut kabel listrik seluruh gedung"},{"id":"opt_3","text":"Segera menghentikan mesin dan memanggil penanggung jawab"},{"id":"opt_4","text":"Menekan tombol hijau tiga kali"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '赤いランプがついたら (jika lampu merah menyala) + 機械を止めて責任者を呼んでください.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan teman. Apa rencana pembicara setelah lulus ujian N4?', '{"audio_text":"N4に合格したら、次は介護の特定技能試験に挑戦したいです。","options":[{"id":"opt_1","text":"Langsung berhenti belajar bahasa Jepang"},{"id":"opt_2","text":"Pindah ke negara lain"},{"id":"opt_3","text":"Mengulang ujian N5"},{"id":"opt_4","text":"Ingin mencoba ujian Tokutei Ginou bidang keperawatan (Kaigo)"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'N4に合格したら (setelah lulus N4) + 介護の特定技能試験に挑戦したい (ingin menantang ujian Tokutei Ginou Kaigo).', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan petunjuk arah ini. Belok di mana setelah keluar dari pintu timur?', '{"audio_text":"東口を出たら、すぐ右へ曲がってまっすぐ歩いてください。","options":[{"id":"opt_1","text":"Segera belok kanan lalu jalan lurus"},{"id":"opt_2","text":"Belok kiri lalu menyeberang jembatan"},{"id":"opt_3","text":"Naik bus nomor lima di depan stasiun"},{"id":"opt_4","text":"Masuk ke gedung di sebelah kiri"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '東口を出たら (setelah keluar pintu timur) + すぐ右へ曲がって (segera belok kanan).', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Ubah 飲みます (minum) ke bentuk ～たら: この薬を___、少し眠くなりますよ。', '{"options":["飲いたら","飲みたら","飲ったら","飲んだら"],"translation":"Kalau minum obat ini, kamu akan merasa agak mengantuk ya.","sentence_template":"この薬を[blank]、少し眠くなりますよ。"}'::jsonb, '{"selected":"飲んだら"}'::jsonb, '飲みます -> Bentuk TA: 飲んだ + ら = 飲んだら.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengandaian menggunakan kata kerja 買います: もし宝くじに___、両親に家を建ててあげたいです。', '{"options":["当たったら","当たいたら","当たんだら","当たりたら"],"translation":"Seandainya menang lotre, saya ingin membangunkan rumah untuk orang tua.","sentence_template":"もし宝くじに[blank]、両親に家を建ててあげたいです。"}'::jsonb, '{"selected":"当たったら"}'::jsonb, '当たります (menang/kena) -> 当たった + ら = 当たったら.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi instruksi prosedur penggunaan mesin: カードを___、暗証番号を入力してください。', '{"options":["入れますら","入れたら","入ったら","入れるたら"],"translation":"Setelah memasukkan kartu, silakan masukkan nomor PIN Anda.","sentence_template":"カードを[blank]、暗証番号を入力してください。"}'::jsonb, '{"selected":"入れたら"}'::jsonb, '入れます (memasukkan, transitif) -> 入れた + ら = 入れたら.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah pukul lima, kita bisa pulang."', '{"display_text":"五時になったら、帰ってもいいですよ。","romaji":"Goji ni nattara, kaette mo ii desu yo.","phonetic_breakdown":["go-ji","ni","nat-ta-ra","ka-et-te","mo","i-i","de-su","yo"]}'::jsonb, '{"expected_transcript":"五時になったら、帰ってもいいですよ。"}'::jsonb, 'なります -> なった + ら = なったら (kalau sudah menjadi jam 5).', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau terjadi kesalahan, tolong segera beri tahu saya."', '{"display_text":"間違いがあったら、すぐ教えてください。","romaji":"Machigai ga attara, sugu oshiete kudasai.","phonetic_breakdown":["ma-chi-ga-i","ga","at-ta-ra","su-gu","o-shi-e-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"間違いがあったら、すぐ教えてください。"}'::jsonb, '間違いがあったら (jika ada kesalahan) adalah frasa wajib dalam pemeriksaan dokumen di kantor.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah pulang ke Indonesia, saya ingin membuka restoran Jepang."', '{"display_text":"インドネシアへ帰ったら、日本料理の店を開きたいです。","romaji":"Indoneshia e kaettara, Nihon ryouri no mise o hirakitai desu.","phonetic_breakdown":["in-do-ne-shi-a","e","ka-et-ta-ra","ni-hon","ryo-u-ri","no","mi-se","o","hi-ra-ki-ta-i","de-su"]}'::jsonb, '{"expected_transcript":"インドネシアへ帰ったら、日本料理の店を開きたいです。"}'::jsonb, '帰ります -> 帰った + ら = 帰ったら menyatakan rencana setelah pulang ke tanah air.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau musim semi tiba, bunga sakura akan mekar."', '{"tokens":["なったら、","雪が","春に","なります、","桜が","咲きます。"],"target_translation":"Kalau musim semi tiba, bunga sakura akan mekar.","romaji":"Haru ni nattara, sakura ga sakimasu."}'::jsonb, '["春に","なったら、","桜が","咲きます。"]'::jsonb, '春になったら (kalau musim semi tiba) + 桜が咲きます (sakura mekar).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau makan siang selesai, ayo kita rapat sebentar."', '{"tokens":["少し","食べ終わったら、","打ち合わせをしましょう。","寝ましょう。","昼ご飯を","食べます、"],"target_translation":"Kalau makan siang selesai, ayo kita rapat sebentar.","romaji":"Hirugohan o tabeowattara, sukoshi uchiawase o shimashou."}'::jsonb, '["昼ご飯を","食べ終わったら、","少し","打ち合わせをしましょう。"]'::jsonb, '打ち合わせ (uchiawase) adalah rapat singkat/koordinasi; 食べ終わったら berarti setelah selesai makan.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau tubuhmu tidak enak, jangan memaksakan diri."', '{"tokens":["具合が","してください。","悪いったら、","悪かったら、","しないでください。","無理を"],"target_translation":"Kalau tubuhmu tidak enak, jangan memaksakan diri.","romaji":"Guai ga warukattara, muri o shinaide kudasai."}'::jsonb, '["具合が","悪かったら、","無理を","しないでください。"]'::jsonb, '悪い (Adjektiva-I) -> 悪かった + ら = 悪かったら.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk ～たら yang benar untuk Adjektiva-I いい (bagus): 都合が___、来週一緒に食事しませんか。', '{"options":["いいったら","よくったら","よかったら","いかったら"],"translation":"Kalau waktumu cocok, maukah makan bersama minggu depan?","sentence_template":"都合が[blank]、来週一緒に食事しませんか。"}'::jsonb, '{"selected":"よかったら"}'::jsonb, 'いい memiliki bentuk lampau tidak beraturan よかった, sehingga menjadi よかったら.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengandaian menggunakan kata kerja 来ます (datang): 大阪へ___、ぜひ連絡してくださいね。', '{"options":["来いたら","来るたら","来ったら","来たら"],"translation":"Kalau kamu datang ke Osaka, pastikan hubungi saya ya.","sentence_template":"大阪へ[blank]、ぜひ連絡してくださいね。"}'::jsonb, '{"selected":"来たら"}'::jsonb, '来ます (kimasu) -> Bentuk TA: 来た (kita) + ら = 来たら (kitara).', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan di minimarket. Kapan pelanggan mendapat potongan harga?', '{"audio_text":"こちらのアプリを登録していただいたら、今日のお会計から百円引きになります。","options":[{"id":"opt_1","text":"Jika membayar dengan uang tunai"},{"id":"opt_2","text":"Jika mendaftarkan aplikasi toko tersebut, mendapat diskon seratus yen"},{"id":"opt_3","text":"Jika berbelanja di atas sepuluh ribu yen"},{"id":"opt_4","text":"Jika datang sebelum jam tujuh pagi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '登録していただいたら (jika berkenan mendaftar aplikasi) -> 百円引き (potongan 100 yen).', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan dari manajer. Apa yang diminta setelah laporan diperiksa?', '{"audio_text":"数字を確認したら、そのまま部長の机の上に置いておいてください。","options":[{"id":"opt_1","text":"Menghapus file laporan dari komputer"},{"id":"opt_2","text":"Mengirim laporan lewat pos"},{"id":"opt_3","text":"Meletakkan laporan di atas meja manajer setelah memeriksa angkanya"},{"id":"opt_4","text":"Menunggu manajer kembali sampai malam"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '数字を確認したら (setelah memeriksa angkanya) + 部長の机の上に置いておいてください.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kalau tombol ini ditekan, pintu otomatis akan terbuka."', '{"tokens":["このボタンを","開きます。","押したら、","閉まります。","押します、","自動ドアが"],"target_translation":"Kalau tombol ini ditekan, pintu otomatis akan terbuka.","romaji":"Kono botan o oshitara, jidou doa ga akimasu."}'::jsonb, '["このボタンを","押したら、","自動ドアが","開きます。"]'::jsonb, '押します (menekan) -> 押した + ら = 押したら.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau ada pertanyaan tentang kontrak, silakan hubungi kantor."', '{"display_text":"契約について質問があったら、事務所までご連絡ください。","romaji":"Keiyaku ni tsuite shitsumon ga attara, jimusho made gorenraku kudasai.","phonetic_breakdown":["ke-i-ya-ku","ni","tsu-i-te","shi-tsu-mon","ga","at-ta-ra","ji-mu-sho","ma-de","go-ren-ra-ku","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"契約について質問があったら、事務所までご連絡ください。"}'::jsonb, '契約 (keiyaku) berarti kontrak; 質問があったら sangat sering dipakai dalam surat dan percakapan resmi.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang berarti ''memesan terlebih dahulu'': 出張の前に、新幹線とホテルを___しておきます。', '{"options":["予約","見学","遅刻","質問"],"translation":"Sebelum perjalanan dinas, saya memesan Shinkansen dan hotel lebih dulu.","sentence_template":"出張の前に、新幹線とホテルを[blank]しておきます。"}'::jsonb, '{"selected":"予約"}'::jsonb, '予約する (yoyaku suru) berarti membuat reservasi/pemesanan.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata persiapan pelajaran/rapat: 明日の授業のために、新しい単語を___しておきます。', '{"options":["洗濯","予習","散歩","買い物"],"translation":"Untuk kelas besok, saya mempelajari kosakata baru terlebih dahulu.","sentence_template":"明日の授業のために、新しい単語を[blank]しておきます。"}'::jsonb, '{"selected":"予習"}'::jsonb, '予習 (yoshuu) berarti belajar pendahuluan sebelum pelajaran dimulai (lawan dari 復習 = mengulang).', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan persiapan perjalanan ini. Apa yang sudah diperiksa?', '{"audio_text":"明日の出発前に、電車の乗り換え時間を調べておきました。","options":[{"id":"opt_1","text":"Harga suvenir di bandara"},{"id":"opt_2","text":"Cuaca minggu depan"},{"id":"opt_3","text":"Menu sarapan di hotel"},{"id":"opt_4","text":"Waktu transit kereta sebelum berangkat besok"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '乗り換え時間 (norikae jikan) adalah waktu pindah/transit kereta; 調べておきました berarti sudah dicari tahu sebelumnya.', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rumah tangga ini. Apa yang akan dilakukan sebelum tamu tiba?', '{"audio_text":"お客様が来る前に、冷たいお茶を用意しておきますね。","options":[{"id":"opt_1","text":"Menyiapkan teh dingin sebelum tamu datang"},{"id":"opt_2","text":"Memesan makanan dari luar"},{"id":"opt_3","text":"Mematikan lampu ruang tamu"},{"id":"opt_4","text":"Pergi berbelanja ke supermarket"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '用意しておきます berarti akan menyiapkan terlebih dahulu untuk kedatangan tamu.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum rapat dimulai, saya memfotokopi materi terlebih dahulu."', '{"tokens":["コピーして","おきます。","資料を","会議の前に、","コピーします。","あります。"],"target_translation":"Sebelum rapat dimulai, saya memfotokopi materi terlebih dahulu.","romaji":"Kaigi no mae ni, shiryou o kopii shite okimasu."}'::jsonb, '["会議の前に、","資料を","コピーして","おきます。"]'::jsonb, 'コピーしておきます menyatakan tindakan aktif menyiapkan fotokopi sebelum rapat.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan mengecas ponsel sebelum tidur malam ini."', '{"display_text":"今夜寝る前に、スマホを充電しておきます。","romaji":"Konya neru mae ni, sumaho o juuden shite okimasu.","phonetic_breakdown":["kon-ya","ne-ru","ma-e","ni","su-ma-ho","o","ju-u-den","shi-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"今夜寝る前に、スマホを充電しておきます。"}'::jsonb, '充電する (juuden suru) berarti mengisi daya baterai; ～ておきます menekankan persiapan untuk besok.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola tindakan persiapan sebelum acara: パーティーの前に、飲み物を冷やして___。', '{"options":["みます","しまいます","おきます","あります"],"translation":"Sebelum pesta, saya akan mendinginkan minuman terlebih dahulu.","sentence_template":"パーティーの前に、飲み物を冷やして[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, '～ておきます digunakan saat subjek melakukan tindakan persiapan demi keperluan yang akan datang.', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk TE yang benar untuk 買います (membeli): 旅行の前に、新しいカメラを___おきたいです。', '{"options":["買いて","買んで","買いって","買って"],"translation":"Sebelum berwisata, saya ingin membeli kamera baru terlebih dahulu.","sentence_template":"旅行の前に、新しいカメラを[blank]おきたいです。"}'::jsonb, '{"selected":"買って"}'::jsonb, '買います -> Bentuk TE: 買って + おきたいです.', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi bentuk permintaan persiapan lebih awal: 明日までにこの書類を読んで___。', '{"options":["おいてください","おかないください","おったください","おきますください"],"translation":"Tolong baca dokumen ini terlebih dahulu paling lambat besok.","sentence_template":"明日までにこの書類を読んで[blank]。"}'::jsonb, '{"selected":"おいてください"}'::jsonb, 'おきます diubah ke bentuk TE (おいて) lalu ditambah ください -> 読んでおいてください.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tolong nyalakan AC sebelum tamu datang."', '{"tokens":["お客様が来る前に、","エアコンを","あります。","消して","おいてください。","つけて"],"target_translation":"Tolong nyalakan AC sebelum tamu datang.","romaji":"Okyakusama ga kuru mae ni, eakon o tsukete oite kudasai."}'::jsonb, '["お客様が来る前に、","エアコンを","つけて","おいてください。"]'::jsonb, 'つけておいてください meminta agar AC dinyalakan lebih awal agar ruangan sudah sejuk saat tamu tiba.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya sudah memesan restoran untuk makan malam besok."', '{"tokens":["予約して","食べました。","明日のために、","レストランを","予約します。","おきました。"],"target_translation":"Saya sudah memesan restoran untuk makan malam besok.","romaji":"Ashita no tame ni, resutoran o yoyaku shite okimashita."}'::jsonb, '["明日のために、","レストランを","予約して","おきました。"]'::jsonb, '予約しておきました menyatakan reservasi sudah dilakukan sebelumnya sebagai persiapan.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tolong bereskan meja ini setelah selesai dipakai ya."', '{"display_text":"使い終わったら、この机を片付けておいてください。","romaji":"Tsukaiowattara, kono tsukue o katazukete oite kudasai.","phonetic_breakdown":["tsu-ka-i-o-wat-ta-ra","ko-no","tsu-ku-e","o","ka-ta-zu-ke-te","o-i-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"使い終わったら、この机を片付けておいてください。"}'::jsonb, '片付けておいてください berarti tolong rapikan agar siap dipakai berikutnya.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Apa yang diminta senior sebelum rapat jam dua?', '{"audio_text":"二時から会議ですから、ホワイトボードをきれいにしておいてくれますか。","options":[{"id":"opt_1","text":"Membuat kopi untuk sepuluh orang"},{"id":"opt_2","text":"Membersihkan papan tulis sebelum rapat jam dua"},{"id":"opt_3","text":"Mengirim undangan rapat baru"},{"id":"opt_4","text":"Mematikan proyektor ruang rapat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'ホワイトボードをきれいにしておいてくれますか meminta membersihkan papan tulis sebelumnya.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan tentang penggunaan alat. Apa arti kalimat ''そのままにしておいてください''?', '{"audio_text":"その資料はまだ使いますから、机の上にそのままにしておいてください。","options":[{"id":"opt_1","text":"Tolong buang dokumen itu sekarang juga"},{"id":"opt_2","text":"Tolong fotokopi dokumen itu dua kali"},{"id":"opt_3","text":"Tolong biarkan dokumen itu apa adanya di atas meja karena masih dipakai"},{"id":"opt_4","text":"Tolong simpan dokumen itu di gudang"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'そのままにしておく adalah penggunaan penting ～ておく yang berarti ''membiarkan dalam kondisi seperti itu''.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan persiapan sebelum pulang kampung. Apa yang sudah dilakukan pembicara?', '{"audio_text":"来週帰国するので、友達へのお土産をもう買っておきました。","options":[{"id":"opt_1","text":"Ia baru akan membeli oleh-oleh di bandara"},{"id":"opt_2","text":"Ia membatalkan kepulangannya minggu depan"},{"id":"opt_3","text":"Ia lupa membeli oleh-oleh"},{"id":"opt_4","text":"Ia sudah membeli oleh-oleh untuk teman sebelumnya"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'お土産をもう買っておきました berarti sudah membeli oleh-oleh sebelumnya.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk TE yang tepat untuk 調べます (mencari tahu): 面接の前に、会社のことをよく___おいたほうがいいです。', '{"options":["調べいて","調べて","調べって","調べんで"],"translation":"Sebelum wawancara, sebaiknya mencari tahu tentang perusahaan itu dengan baik lebih dulu.","sentence_template":"面接の前に、会社のことをよく[blank]おいたほうがいいです。"}'::jsonb, '{"selected":"調べて"}'::jsonb, '調べます (Grup 2) -> Bentuk TE: 調べて + おいたほうがいいです.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat membiarkan jendela tetap terbuka: 少し暑いので、窓を開けて___いいですか。', '{"options":["おきますも","おいたも","おいても","おかないも"],"translation":"Karena agak panas, bolehkah jendela dibiarkan tetap terbuka?","sentence_template":"少し暑いので、窓を開けて[blank]いいですか。"}'::jsonb, '{"selected":"おいても"}'::jsonb, '開けておいてもいいですか berarti ''bolehkah dibiarkan terbuka?''.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat menyimpan uang demi masa depan: 将来のために、毎月少しずつ貯金して___。', '{"options":["いきますか","きますか","あります","おきます"],"translation":"Demi masa depan, saya menabung sedikit demi sedikit setiap bulan.","sentence_template":"将来のために、毎月少しずつ貯金して[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, '貯金しておきます menekankan menabung sebagai persiapan masa depan.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan menulis catatan dulu supaya tidak lupa."', '{"display_text":"忘れないように、メモに書いておきます。","romaji":"Wasurenai you ni, memo ni kaite okimasu.","phonetic_breakdown":["wa-su-re-na-i","yo-u","ni","me-mo","ni","ka-i-te","o-ki-ma-su"]}'::jsonb, '{"expected_transcript":"忘れないように、メモに書いておきます。"}'::jsonb, '忘れないように (supaya tidak lupa) sangat sering berpasangan dengan 書いておきます.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum berangkat, saya sudah menutup semua jendela."', '{"display_text":"出かける前に、窓を全部閉めておきました。","romaji":"Dekakeru mae ni, mado o zenbu shimete okimashita.","phonetic_breakdown":["de-ka-ke-ru","ma-e","ni","ma-do","o","zen-bu","shi-me-te","o-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"出かける前に、窓を全部閉めておきました。"}'::jsonb, '閉めておきました menunjukkan tindakan pencegahan/persiapan sebelum meninggalkan rumah.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tolong siapkan paspor dan tiket pesawat sejak malam ini."', '{"display_text":"今夜のうちに、パスポートと航空券を用意しておいてください。","romaji":"Konya no uchi ni, pasupooto to koukuuken o youi shite oite kudasai.","phonetic_breakdown":["kon-ya","no","u-chi","ni","pa-su-po-o-to","to","ko-u-ku-u-ken","o","yo-u-i","shi-te","o-i-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"今夜のうちに、パスポートと航空券を用意しておいてください。"}'::jsonb, '航空券 (koukuuken) berarti tiket pesawat; 用意しておいてください meminta menyiapkan sejak malam ini.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebelum ujian dimulai, saya sudah menajamkan pensil."', '{"tokens":["試験の前に、","おきました。","忘れました。","削ります。","鉛筆を","削って"],"target_translation":"Sebelum ujian dimulai, saya sudah menajamkan pensil.","romaji":"Shiken no mae ni, enpitsu o kezutte okimashita."}'::jsonb, '["試験の前に、","鉛筆を","削って","おきました。"]'::jsonb, '削ります (meraut/menajamkan) -> 削っておきました.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Biar saya saja yang membersihkan ruang rapat dulu."', '{"tokens":["先に","掃除して","私が","掃除します。","おきますね。","帰ります。","会議室を"],"target_translation":"Biar saya saja yang membersihkan ruang rapat dulu.","romaji":"Watashi ga saki ni kaigishitsu o souji shite okimasu ne."}'::jsonb, '["私が","先に","会議室を","掃除して","おきますね。"]'::jsonb, '先に...しておきますね adalah ungkapan proaktif yang sangat dihargai di lingkungan kerja Jepang.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tolong biarkan lampu lorong tetap menyala."', '{"tokens":["廊下の電気は","あります。","おいてください。","そのまま","つけて","消して"],"target_translation":"Tolong biarkan lampu lorong tetap menyala.","romaji":"Rouka no denki wa sono mama tsukete oite kudasai."}'::jsonb, '["廊下の電気は","そのまま","つけて","おいてください。"]'::jsonb, 'そのままつけておいてください berarti tolong biarkan tetap menyala.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk percakapan kasual (kontraksi) dari ～ておく yang sering muncul di audio N4: 明日早いから、今夜のうちに荷物を準備し___よ。', '{"options":["とく","てる","みる","ちゃう"],"translation":"Karena besok berangkat pagi, malam ini aku siapkan barang-barang dulu ya.","sentence_template":"明日早いから、今夜のうちに荷物を準備し[blank]よ。"}'::jsonb, '{"selected":"とく"}'::jsonb, 'Dalam percakapan sehari-hari, ～ておく sering disingkat menjadi ～とく (準備しておく -> 準備しとく).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Bedakan pola aksi persiapan vs laporan keadaan hasil aksi: 明日のプレゼンのために、今晩よく練習して___。', '{"options":["きました","おきます","いますか","あります"],"translation":"Demi presentasi besok, malam ini saya akan berlatih dengan baik terlebih dahulu.","sentence_template":"明日のプレゼンのために、今晩よく練習して[blank]。"}'::jsonb, '{"selected":"おきます"}'::jsonb, 'Karena menyatakan rencana tindakan aktif yang akan dilakukan subjek (今晩), gunakan 練習しておきます.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja. Apa yang sudah dilakukan Sato untuk rapat sore?', '{"audio_text":"佐藤さん、午後の資料はどうですか。はい、すでに全員の机に配っておきました。","options":[{"id":"opt_1","text":"Sato sudah membagikan materi ke meja semua peserta sebelumnya"},{"id":"opt_2","text":"Sato belum mencetak materi rapat"},{"id":"opt_3","text":"Sato akan membagikan materi setelah rapat"},{"id":"opt_4","text":"Sato meminta orang lain membagikan materi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '配っておきました berarti sudah dibagikan sebelumnya sebagai persiapan.', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan ibu sebelum pergi. Apa yang diminta kepada anaknya?', '{"audio_text":"夕方雨が降りそうだから、外に出る前に洗濯物を取り込んでおいてね。","options":[{"id":"opt_1","text":"Menjemur pakaian baru di luar"},{"id":"opt_2","text":"Memasukkan jemuran sebelum keluar rumah karena sepertinya sore akan hujan"},{"id":"opt_3","text":"Mencuci pakaian dengan mesin cuci"},{"id":"opt_4","text":"Menyetrika seragam sekolah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '洗濯物を取り込んでおいてね berarti tolong angkat/masukkan jemuran terlebih dahulu.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menelepon dokter dulu untuk membuat janji."', '{"tokens":["おきます。","忘れます。","病院に","取って","電話して、","予約を","取ります。"],"target_translation":"Saya akan menelepon dokter dulu untuk membuat janji.","romaji":"Byouin ni denwa shite, yoyaku o totte okimasu."}'::jsonb, '["病院に","電話して、","予約を","取って","おきます。"]'::jsonb, '予約を取ります (membuat janji temu) -> 予約を取っておきます.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebelum pindah rumah, saya harus mengurus prosedur di balai kota dulu."', '{"display_text":"引っ越す前に、市役所で手続きをしておかなければなりません。","romaji":"Hikkosu mae ni, shiyakusho de tetsuzuki o shite okanakereba narimasen.","phonetic_breakdown":["hik-ko-su","ma-e","ni","shi-ya-ku-sho","de","te-tsu-zu-ki","o","shi-te","o-ka-na-ke-re-ba","na-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"引っ越す前に、市役所で手続きをしておかなければなりません。"}'::jsonb, 'Kombinasi ～ておく + ～なければなりません berarti ''harus mempersiapkan terlebih dahulu''.', 6);
    INSERT INTO units (level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang berarti ''kartu nama'': 初めて会った取引先の方と___を交換しました。', '{"options":["定期券","領収書","名刺","切手"],"translation":"Saya bertukar kartu nama dengan mitra bisnis yang baru pertama kali ditemui.","sentence_template":"初めて会った取引先の方と[blank]を交換しました。"}'::jsonb, '{"selected":"名刺"}'::jsonb, '名刺 (meishi) berarti kartu nama; 名刺を交換する adalah etika bisnis dasar di Jepang.', 1),
        (v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kosakata staf penanggung jawab: ただいま___がまいりますので、少々お待ちください。', '{"options":["観光客","留学生","運転手","担当者"],"translation":"Staf penanggung jawab akan segera datang, mohon tunggu sebentar.","sentence_template":"ただいま[blank]がまいりますので、少々お待ちください。"}'::jsonb, '{"selected":"担当者"}'::jsonb, '担当者 (tantousha) berarti orang yang bertanggung jawab menangani urusan tersebut.', 2),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan sapaan di meja resepsionis. Apa maksud ucapan staf ini?', '{"audio_text":"いらっしゃいませ。ご予約のお名前を伺ってもよろしいでしょうか。","options":[{"id":"opt_1","text":"Menawarkan minuman kepada tamu"},{"id":"opt_2","text":"Menunjukkan arah toilet"},{"id":"opt_3","text":"Menanyakan nama pemesan secara sangat sopan"},{"id":"opt_4","text":"Meminta tamu membayar di muka"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '伺う (ukagau) adalah bentuk kenjougo dari 聞く (bertanya/mendengar).', 3),
        (v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan salam perkenalan bisnis ini. Siapa nama pembicara?', '{"audio_text":"はじめまして、インドネシアからまいりました、アリと申します。","options":[{"id":"opt_1","text":"Namanya Indonesia"},{"id":"opt_2","text":"Namanya Mairimashita"},{"id":"opt_3","text":"Namanya belum disebutkan"},{"id":"opt_4","text":"Namanya Ari, datang dari Indonesia"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'アリと申します (Ari to moushimasu) adalah bentuk merendah sangat sopan untuk memperkenalkan nama.', 4),
        (v_lesson_id, NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan memandu Anda ke ruang rapat."', '{"tokens":["ご案内","いたします。","会議室まで","行きます。","食べます。"],"target_translation":"Saya akan memandu Anda ke ruang rapat.","romaji":"Kaigishitsu made go-annai itashimasu."}'::jsonb, '["会議室まで","ご案内","いたします。"]'::jsonb, 'ご + [Nomina verba] + いたします (ご案内いたします) adalah pola Kenjougo bisnis yang sangat sopan.', 5),
        (v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya sudah mengerti, segera saya kerjakan."', '{"display_text":"かしこまりました。すぐに対応いたします。","romaji":"Kashikomarimashita. Sugu ni taiou itashimasu.","phonetic_breakdown":["ka-shi-ko-ma-ri-ma-shi-ta","su-gu","ni","ta-i-o-u","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"かしこまりました。すぐに対応いたします。"}'::jsonb, 'かしこまりました adalah bentuk sangat sopan dari わかりました, dan 対応いたします berarti segera saya tangani.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola Kenjougo お + [Akar Masu] + します untuk 持ちます (membawa): お荷物を___。', '{"options":["お持ちします","持ちられます","持ってあります","お持ちになります"],"translation":"Biar saya yang membawakan barang bawaan Anda.","sentence_template":"お荷物を[blank]。"}'::jsonb, '{"selected":"お持ちします"}'::jsonb, 'Kenjougo merendahkan tindakan pembicara sendiri: お + 持ち + します -> お持ちします. (お持ちになります adalah Sonkeigo untuk lawan bicara).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Kenjougo khusus dari 行きます / 来ます (pergi / datang): 明日、十時にそちらへ___。', '{"options":["なさいます","まいります","おっしゃいます","いらっしゃいます"],"translation":"Besok pukul sepuluh saya akan datang ke tempat Anda.","sentence_template":"明日、十時にそちらへ[blank]。"}'::jsonb, '{"selected":"まいります"}'::jsonb, 'まいります adalah Kenjougo dari 行きます/来ます (dipakai untuk tindakan pembicara sendiri).', 2),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Kenjougo khusus dari 言います (mengatakan / bernama): 私は桜株式会社の田中と___。', '{"options":["召し上がります","おっしゃいます","申します","ご覧になります"],"translation":"Nama saya Tanaka dari PT Sakura.","sentence_template":"私は桜株式会社の田中と[blank]。"}'::jsonb, '{"selected":"申します"}'::jsonb, '申します (moushimasu) adalah bentuk merendah dari 言います, wajib dipakai saat memperkenalkan diri secara formal.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan membawakan dokumen itu sekarang."', '{"tokens":["資料を","します。","今すぐ","お持ちになります。","持ちます。","お持ち"],"target_translation":"Saya akan membawakan dokumen itu sekarang.","romaji":"Ima sugu shiryou o omochi shimasu."}'::jsonb, '["今すぐ","資料を","お持ち","します。"]'::jsonb, 'お持ちします merendahkan tindakan pembicara yang membawa dokumen untuk atasan/tamu.', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menelepon Anda kembali nanti."', '{"tokens":["お電話になります。","聞きます。","いたします。","お電話","あとで","こちらから"],"target_translation":"Saya akan menelepon Anda kembali nanti.","romaji":"Ato de kochira kara odenwa itashimasu."}'::jsonb, '["あとで","こちらから","お電話","いたします。"]'::jsonb, 'お電話いたします adalah bentuk Kenjougo yang sangat santun untuk ''saya akan menelepon''.', 5),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan memeriksa jadwalnya terlebih dahulu."', '{"display_text":"ただいまスケジュールを確認いたします。","romaji":"Tadaima sukejuuru o kakunin itashimasu.","phonetic_breakdown":["ta-da-i-ma","su-ke-ju-u-ru","o","ka-ku-nin","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"ただいまスケジュールを確認いたします。"}'::jsonb, 'いたします adalah bentuk merendah dari します -> 確認いたします (saya akan memeriksa).', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ucapan staf hotel ini. Apa yang ia tawarkan kepada tamu?', '{"audio_text":"重そうですね。お部屋までお荷物をお運びいたします。","options":[{"id":"opt_1","text":"Membawakan barang bawaan tamu sampai ke kamar"},{"id":"opt_2","text":"Memanggilkan taksi ke bandara"},{"id":"opt_3","text":"Mengganti kamar tamu dengan yang lebih besar"},{"id":"opt_4","text":"Menyimpan barang tamu di ruang bawah tanah"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お運びいたします (Kenjougo dari 運びます) berarti biar saya bawakan.', 1),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan telepon bisnis ini. Apa yang akan dilakukan staf penerima telepon?', '{"audio_text":"申し訳ございません、山田は席を外しております。戻りましたら、こちらからご連絡いたします。","options":[{"id":"opt_1","text":"Menyambungkan langsung ke Pak Yamada sekarang"},{"id":"opt_2","text":"Menghubungi balik begitu Pak Yamada kembali ke mejanya"},{"id":"opt_3","text":"Meminta penelepon datang ke kantor besok"},{"id":"opt_4","text":"Memberikan nomor ponsel pribadi Pak Yamada"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '席を外しております (sedang tidak di tempat) + ご連絡いたします (kami akan menghubungi balik).', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan perkenalan diri saat wawancara. Bagaimana sikap pembicara?', '{"audio_text":"本日はお忙しい中、お時間をいただきありがとうございます。精一杯頑張ります。","options":[{"id":"opt_1","text":"Meminta jadwal wawancara diundur"},{"id":"opt_2","text":"Menolak tawaran pekerjaan secara halus"},{"id":"opt_3","text":"Mengucapkan terima kasih atas waktu pewawancara dan berjanji berusaha maksimal"},{"id":"opt_4","text":"Menanyakan besaran gaji lembur"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'お時間をいただきありがとうございます adalah ungkapan Kenjougo (いただく) yang sangat sopan.', 3),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Kenjougo dari 見ます (melihat / memeriksa): お送りいただいたメールを___。', '{"options":["ご覧になりました","召し上がりました","おっしゃいました","拝見しました"],"translation":"Saya sudah membaca email yang Anda kirimkan.","sentence_template":"お送りいただいたメールを[blank]。"}'::jsonb, '{"selected":"拝見しました"}'::jsonb, '拝見します (haiken shimasu) adalah Kenjougo dari 見ます saat pembicara melihat/membaca sesuatu dari pihak yang dihormati.', 4),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Kenjougo dari 食べます / 飲みます (makan / minum): おいしいお茶を___。ありがとうございます。', '{"options":["いただきました","なさいました","召し上がりました","いらっしゃいました"],"translation":"Saya telah menikmati teh yang lezat ini. Terima kasih banyak.","sentence_template":"おいしいお茶を[blank]。ありがとうございます。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, 'いただきます adalah Kenjougo untuk menerima/makan/minum dari pihak lain. 召し上がります adalah Sonkeigo.', 5),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola Kenjougo ご + [Nomina verba] + いたします (menjelaskan): これから本日の予定をご___いたします。', '{"options":["歩き","説明","食べ","飲み"],"translation":"Sekarang saya akan menjelaskan jadwal hari ini.","sentence_template":"これから本日の予定をご[blank]いたします。"}'::jsonb, '{"selected":"説明"}'::jsonb, 'Untuk kata kerja Grup 3 (Kango + する) seperti 説明する, bentuk Kenjougo-nya adalah ご説明いたします.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya akan mengirimkan dokumennya lewat email hari ini."', '{"display_text":"本日中に資料をメールでお送りいたします。","romaji":"Honjitsuchuu ni shiryou o meeru de ookuri itashimasu.","phonetic_breakdown":["hon-ji-tsu-chu-u","ni","shi-ryo-u","o","me-e-ru","de","o-o-ku-ri","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"本日中に資料をメールでお送りいたします。"}'::jsonb, '送ります -> お送りいたします sangat sering dipakai dalam korespondensi bisnis Jepang.', 1),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya sudah menerima kartu nama Anda dengan hormat."', '{"display_text":"頂戴いたします。ありがとうございます。","romaji":"Choudai itashimasu. Arigatou gozaimasu.","phonetic_breakdown":["cho-u-da-i","i-ta-shi-ma-su","a-ri-ga-to-u","go-za-i-ma-su"]}'::jsonb, '{"expected_transcript":"頂戴いたします。ありがとうございます。"}'::jsonb, '頂戴いたします adalah ungkapan Kenjougo saat menerima kartu nama atau pemberian dari klien/atasan.', 2),
        (v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Biar saya yang memanggilkan taksi untuk Anda."', '{"display_text":"私がタクシーをお呼びいたします。","romaji":"Watashi ga takushii o oyobi itashimasu.","phonetic_breakdown":["wa-ta-shi","ga","ta-ku-shi-i","o","o-yo-bi","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"私がタクシーをお呼びいたします。"}'::jsonb, '呼びます -> お呼びいたします merendahkan tindakan pembicara yang melayani tamu.', 3),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan segera menghubungi kepala bagian."', '{"tokens":["ご連絡になります。","連絡しますか。","課長へ","いたします。","ご連絡","すぐに"],"target_translation":"Saya akan segera menghubungi kepala bagian.","romaji":"Sugu ni kachou e gorenraku itashimasu."}'::jsonb, '["すぐに","課長へ","ご連絡","いたします。"]'::jsonb, 'ご連絡いたします (Kenjougo dari 連絡します).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya akan menyiapkan kopi untuk Anda."', '{"tokens":["コーヒーを","ご用意になります。","いたします。","ご用意","飲みます。"],"target_translation":"Saya akan menyiapkan kopi untuk Anda.","romaji":"Koohii o goyoui itashimasu."}'::jsonb, '["コーヒーを","ご用意","いたします。"]'::jsonb, '用意する (menyiapkan) -> ご用意いたします.', 5),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya sudah membaca surat dari Bapak dengan baik."', '{"tokens":["拝見","読みます。","ご覧になりました。","いたしました。","社長からの","お手紙を"],"target_translation":"Saya sudah membaca surat dari Bapak dengan baik.","romaji":"Shachou kara no otegami o haiken itashimashita."}'::jsonb, '["社長からの","お手紙を","拝見","いたしました。"]'::jsonb, '拝見いたしました adalah Kenjougo paling halus untuk ''saya telah membaca/melihat''.', 6);
    INSERT INTO lessons (unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Review N4: Pilih kalimat Kenjougo yang tepat saat pembicara mengunjungi kantor klien: 来週の火曜日に、御社へ___。', '{"options":["おっしゃいます","なさいます","伺います","いらっしゃいます"],"translation":"Hari Selasa minggu depan, saya akan berkunjung ke perusahaan Anda.","sentence_template":"来週の火曜日に、御社へ[blank]。"}'::jsonb, '{"selected":"伺います"}'::jsonb, '伺います (ukagaimasu) adalah Kenjougo dari 行きます/訪問します (mengunjungi pihak yang dihormati).', 1),
        (v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Review Terpadu N4: Lengkapi kalimat yang menggabungkan alasan halus dan permohonan sangat sopan: 資料に少し間違いがあるようですので、もう一度確認して___。', '{"options":["あげませんか","おきますか","あります","いただけませんか"],"translation":"Karena sepertinya ada sedikit kesalahan pada dokumen, bersediakah Anda memeriksanya sekali lagi?","sentence_template":"資料に少し間違いがあるようですので、もう一度確認して[blank]。"}'::jsonb, '{"selected":"いただけませんか"}'::jsonb, 'Gabungan ～ので (alasan halus) + ～ていただけませんか (permohonan sangat sopan) adalah pola inti JLPT N4.', 2),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan bisnis terpadu N4 ini. Apa yang akan dilakukan staf setelah memeriksa jadwal?', '{"audio_text":"申し訳ございません、ただいま担当者が外出しておりますので、戻り次第ご連絡いたします。","options":[{"id":"opt_1","text":"Menyuruh tamu datang kembali minggu depan"},{"id":"opt_2","text":"Meminta tamu menelepon nomor lain"},{"id":"opt_3","text":"Menutup kantor lebih cepat hari ini"},{"id":"opt_4","text":"Menghubungi kembali segera setelah staf penanggung jawab pulang ke kantor"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '外出しております (sedang keluar kantor) + 戻り次第ご連絡いたします (akan menghubungi begitu kembali).', 3),
        (v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan penutup pelatihan kerja ini. Apa pesan utama instruktur?', '{"audio_text":"わからないことがあったら、一人で悩まないで、すぐ先輩に相談したほうがいいですよ。","options":[{"id":"opt_1","text":"Jika ada hal yang tidak dipahami, sebaiknya segera berkonsultasi dengan senior dan tidak memikirkannya sendirian"},{"id":"opt_2","text":"Semua masalah harus diselesaikan sendiri tanpa bertanya"},{"id":"opt_3","text":"Bertanya hanya boleh dilakukan pada hari Jumat"},{"id":"opt_4","text":"Senior tidak boleh diganggu saat jam kerja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'Kalimat ini memadukan ～たら (jika ada) + ～たほうがいい (sebaiknya berkonsultasi).', 4),
        (v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Besok pukul sembilan saya akan datang ke kantor Anda."', '{"tokens":["御社へ","いらっしゃいます。","おっしゃいます。","明日","九時に","まいります。"],"target_translation":"Besok pukul sembilan saya akan datang ke kantor Anda.","romaji":"Ashita kuji ni onsha e mairimasu."}'::jsonb, '["明日","九時に","御社へ","まいります。"]'::jsonb, '御社 (onsha) berarti perusahaan lawan bicara; まいります adalah Kenjougo dari 行きます/来ます.', 5),
